import { writeFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { createEngine, heroReady, mulberry32 } from '../src/core/index.js';
import { ROSTER_CAP } from '../src/core/collection.js';

type Profile = 'active' | 'idle' | 'intermittent';

function run(profile: Profile, seed: number) {
  const engine = createEngine(null, mulberry32(seed));
  let lastKill = 0;
  const gaps: number[] = [];
  const cycles: { startSec: number; lvl12Sec: number | null; kills: number; killsFirstHalf: number; killsSecondHalf: number; endIndex: number; souls: number }[] = [];
  let cur = { startSec: 0, lvl12Sec: null as number | null, kills: 0, killsFirstHalf: 0, killsSecondHalf: 0, endIndex: 0, souls: 0 };
  let voidedCaptures = 0;
  let bossKills = 0;
  let heroDamage = 0n;
  let companionDamage = 0n;
  const killSeconds: number[] = [];
  for (let sec = 1; sec <= 1800; sec++) {
    const inputs = sec <= 120 || profile === 'active' || (profile === 'intermittent' && sec % 60 < 15) ? 2 : 0;
    let killed = false;
    let nKills = 0;
    for (let i = 0; i < inputs; i++) {
      const before = engine.getState();
      const hit = engine.attack('keyboard');
      for (const e of hit) {
        if (e.type === 'attack') heroDamage += e.damage;
        if (e.type === 'monsterKilled') { nKills++; if (e.monster.boss) { bossKills++; if (before.companions.length >= ROSTER_CAP) voidedCaptures++; } }
      }
      killed = nKills > 0 || killed;
    }
    const beforeTick = engine.getState();
    const events = engine.tick(1000);
    for (const e of events) {
      if (e.type === 'companionAttack') companionDamage += e.damage;
      if (e.type === 'monsterKilled') { nKills++; if (e.monster.boss) { bossKills++; if (beforeTick.companions.length >= ROSTER_CAP) voidedCaptures++; } }
    }
    killed = nKills > 0 || killed;
    if (killed) { gaps.push(sec - lastKill); lastKill = sec; killSeconds.push(sec); }
    cur.kills += nKills;
    if (sec - cur.startSec <= 60) cur.killsFirstHalf += nKills; else cur.killsSecondHalf += nKills;
    const state = engine.getState();
    if (state.level >= 12 && cur.lvl12Sec === null) cur.lvl12Sec = sec - cur.startSec;
    if (heroReady(state.level, state.hero)) {
      engine.apply({ type: 'heroOffer' });
      const hero = engine.getState().hero!;
      engine.apply({ type: 'heroChoose', formId: hero.choices[0]!.formId, offerSerial: hero.offerSerial });
      const after = engine.getState();
      cur.endIndex = state.monster.index;
      cur.souls = after.souls;
      cycles.push(cur);
      cur = { startSec: sec, lvl12Sec: null, kills: 0, killsFirstHalf: 0, killsSecondHalf: 0, endIndex: 0, souls: 0 };
    }
  }
  const s = engine.getState();
  return { profile, seed, gaps, cycles, voidedCaptures, bossKills, companions: s.companions.length,
    heroDamage: heroDamage.toString(), companionDamage: companionDamage.toString(),
    heroShare: Number(heroDamage * 10000n / (heroDamage + companionDamage)) / 100,
    collected: s.hero?.collection.length ?? 0, souls: s.souls, killCount: s.killCount, coins: s.coins };
}

describe('scratch designer probe', () => {
  it('probes', () => {
    const out = (['active', 'idle', 'intermittent'] as const).flatMap((p) =>
      Array.from({ length: 20 }, (_, i) => run(p, i + 1)));
    writeFileSync('.agentdoc/v4-fun-post-heroes-20260909/probe.json', JSON.stringify(out));
    expect(out.length).toBe(60);
  }, 120_000);
});

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/** 3 different elements; top unlocked rank guaranteed; unowned forms preferred. */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    let pool = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type) && (i !== 0 || f.rank === rank));
    const unseen = pool.filter((f) => !hero.collection.some((r) => r.formId === f.id));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    if (killed.boss && rng.next() < CAPTURE_CHANCE && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/** 3 different elements; top unlocked rank guaranteed; unowned forms preferred. */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    let pool = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type) && (i !== 0 || f.rank === rank));
    const unseen = pool.filter((f) => !hero.collection.some((r) => r.formId === f.id));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    if (killed.boss && rng.next() < CAPTURE_CHANCE && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

// HUD painting (SPEC F21 + T14/T15 presentation): boxed monster HP bar,
// top-left `LV n` + XP bar, top-right kill/coin counters (with a collection
// pop flash), the pooled floating-damage-number system — numbers rise 8px
// and fade over 600ms; crits draw double-size and yellow (Manual M2) — and
// the flashing "LEVEL UP!" banner (Manual M3).
// DOM-free on purpose — everything draws through SpriteCanvas so the tests
// run under vitest's node environment (same pattern as sprites/sprite.ts).

import { ratio, xpToNext } from '../core/index.js';
import type { Effectiveness, GameState } from '../core/index.js';
import { heroReady } from '../core/hero.js';
import {
  COLORS,
  drawSprite,
  drawText,
  FONT_ADVANCE,
  FONT_H,
  FONT_W,
  fontSprite,
  glyphIndex,
  itemSprites,
  textWidth,
  TRANSPARENT,
} from './sprites/index.js';
import type { SpriteCanvas } from './sprites/index.js';

/** Gap between HUD chrome and the canvas edges, in game pixels. */
export const HUD_MARGIN = 2;
/** Keep counters below the drag strip, closer to the field. */
export const COUNTER_TOP = 16;
/** XP progress bar box size (top-left, under the LV text). */
export const XP_BAR_W = 40;
export const XP_BAR_H = 4;

/**
 * Boxed meter: 1px steel frame, void interior, proportional fill. A non-zero
 * ratio always shows at least 1px of fill; out-of-range/non-finite ratios
 * are clamped so a bad value can never paint outside the box.
 */
export function drawMeter(
  ctx: SpriteCanvas,
  x: number,
  y: number,
  w: number,
  h: number,
  ratio: number,
  fillColor: string,
): void {
  ctx.fillStyle = COLORS.steel;
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(x + 1, y + 1, w - 2, h - 2);
  const clamped = Number.isFinite(ratio) ? Math.min(1, Math.max(0, ratio)) : 0;
  const fill = clamped === 0 ? 0 : Math.max(1, Math.round((w - 2) * clamped));
  if (fill > 0) {
    ctx.fillStyle = fillColor;
    ctx.fillRect(x + 1, y + 1, fill, h - 2);
  }
}

/** Boxed red HP bar (drawn above the monster). */
export function drawHpBar(
  ctx: SpriteCanvas,
  x: number,
  y: number,
  w: number,
  h: number,
  hp: bigint,
  maxHp: bigint,
): void {
  drawMeter(ctx, x, y, w, h, ratio(hp, maxHp), COLORS.red);
}

/**
 * `LV n` text plus the XP progress bar, floating above the hero's head
 * (Assumption 17): `cx` is the hero's horizontal center, `bottom` sits just
 * above the hero's top row — the bar hugs the head, the label rides above it.
 */
export function drawLevelHud(
  ctx: SpriteCanvas,
  state: Readonly<GameState>,
  cx: number,
  bottom: number,
): void {
  const barX = Math.round(cx - XP_BAR_W / 2);
  const barY = bottom - XP_BAR_H;
  drawMeter(ctx, barX, barY, XP_BAR_W, XP_BAR_H, state.xp / xpToNext(state.level), COLORS.cyan);
  const label = `LV ${String(state.level)}`;
  drawText(ctx, label, Math.round(cx - textWidth(label) / 2), barY - FONT_H - 2);
  if (heroReady(state.level, state.hero)) {
    const ready = 'REBIRTH READY';
    drawText(ctx, ready, Math.round(cx - textWidth(ready) / 2), barY - 2 * (FONT_H + 2), { color: COLORS.yellow });
  }
}

/** 5×5 skull marker for the kill counter — HUD chrome, drawn directly. */
function drawSkullIcon(ctx: SpriteCanvas, x: number, y: number): void {
  ctx.fillStyle = COLORS.white;
  ctx.fillRect(x, y, 5, 3); // cranium
  ctx.fillRect(x + 1, y + 3, 3, 2); // jaw
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(x + 1, y + 1, 1, 1); // left eye socket
  ctx.fillRect(x + 3, y + 1, 1, 1); // right eye socket
  ctx.fillRect(x + 2, y + 4, 1, 1); // tooth gap
}

/** How long the coin counter stays "popped" after a drop arrives, ms. */
export const COUNTER_POP_MS = 150;

/**
 * Top-right HUD: skull × killCount row, coin × coins row (right-aligned).
 * While `coinPop` is set (a collected drop just arrived, T15) the coin row
 * pops: the count flashes white and the icon lifts one pixel.
 */
export function drawCounters(
  ctx: SpriteCanvas,
  state: Readonly<GameState>,
  viewW: number,
  coinPop = false,
): void {
  const kills = String(state.killCount);
  const killsX = viewW - HUD_MARGIN - textWidth(kills);
  drawText(ctx, kills, killsX, COUNTER_TOP);
  drawSkullIcon(ctx, killsX - 7, COUNTER_TOP);

  const coins = String(state.coins);
  const coinsX = viewW - HUD_MARGIN - textWidth(coins);
  drawText(ctx, coins, coinsX, COUNTER_TOP + FONT_H + 2, {
    color: coinPop ? COLORS.white : COLORS.yellow,
  });
  const iconY = COUNTER_TOP + FONT_H + (coinPop ? 0 : 1);
  drawSprite(ctx, itemSprites.coin, 0, coinsX - 8, iconY);
}

/** One pooled floating damage number. Slots are reused, never reallocated. */
export interface FloatingNumber {
  active: boolean;
  /** Horizontal center of the text, in game pixels. */
  x: number;
  /** Spawn baseline; the number rises FLOAT_RISE_PX over its lifetime. */
  y: number;
  text: string;
  crit: boolean;
  ageMs: number;
  /** Fresh-phase colour override (companion floats, F64); crit rules if unset. */
  color?: string;
}

/** Fixed pool size — key-mashing can never grow an unbounded array. */
export const FLOAT_POOL_SIZE = 16;
/** Lifetime of one floating number, ms. */
export const FLOAT_LIFE_MS = 600;
/** Total rise over the lifetime, game pixels. */
export const FLOAT_RISE_PX = 14;
/** Age fraction past which a float draws in its dim fade color. */
export const FLOAT_FADE_RATIO = 2 / 3;
/** Pixel scale of normal damage numbers (user change 2026-09-06: readable 2x glyphs with a 1-px outline). */
export const FLOAT_SCALE = 2;
/** Pixel scale of crit damage numbers (Manual M2: crits show larger — 3x, yellow, with a '!'). */
export const CRIT_FLOAT_SCALE = 3;
/** Crits rise this much further than normal floats (same lifetime, punchier). */
export const CRIT_RISE_MULT = 1.5;

export function floatColor(effectiveness: Effectiveness): string {
  return effectiveness === 'super'
    ? COLORS.yellow
    : effectiveness === 'weak'
      ? COLORS.steel
      : COLORS.white;
}

/** Pre-allocate a pool of inactive floating-number slots. */
export function createFloatPool(size: number = FLOAT_POOL_SIZE): FloatingNumber[] {
  return Array.from({ length: size }, () => ({
    active: false,
    x: 0,
    y: 0,
    text: '',
    crit: false,
    ageMs: 0,
  }));
}

/** Activate a slot: the first inactive one, else recycle the oldest active. */
export function spawnFloat(
  pool: FloatingNumber[],
  x: number,
  y: number,
  text: string,
  crit: boolean,
  color?: string,
): void {
  let slot = pool.find((f) => !f.active);
  if (slot === undefined) {
    for (const f of pool) {
      if (slot === undefined || f.ageMs > slot.ageMs) {
        slot = f;
      }
    }
  }
  if (slot === undefined) {
    return; // zero-size pool
  }
  slot.active = true;
  slot.x = x;
  slot.y = y;
  slot.text = text;
  slot.crit = crit;
  slot.color = color;
  slot.ageMs = 0;
}

/** Age every active slot; slots past FLOAT_LIFE_MS deactivate. */
export function tickFloats(pool: FloatingNumber[], dtMs: number): void {
  for (const f of pool) {
    if (!f.active) {
      continue;
    }
    f.ageMs += dtMs;
    if (f.ageMs >= FLOAT_LIFE_MS) {
      f.active = false;
    }
  }
}

/**
 * drawText at an integer pixel scale: every glyph pixel becomes a
 * scale×scale rect. Local to the HUD — the sprite/font modules stay
 * 1px-based (their data is covered by the T11 integrity sweep).
 */
function drawScaledText(
  ctx: SpriteCanvas,
  text: string,
  x: number,
  y: number,
  scale: number,
  color: string,
): void {
  if (scale === 1) {
    drawText(ctx, text, x, y, { color });
    return;
  }
  for (let i = 0; i < text.length; i++) {
    const rows = fontSprite.frames[glyphIndex(text.charAt(i))];
    if (rows === undefined) {
      continue; // unknown chars still advance a cell — stable layout
    }
    for (let ry = 0; ry < FONT_H; ry++) {
      const row = rows[ry];
      if (row === undefined) {
        continue;
      }
      for (let rx = 0; rx < FONT_W; rx++) {
        const ch = row.charAt(rx);
        if (ch === TRANSPARENT || ch === '') {
          continue;
        }
        ctx.fillStyle = color;
        ctx.fillRect(x + (i * FONT_ADVANCE + rx) * scale, y + ry * scale, scale, scale);
      }
    }
  }
}

/**
 * Draw active floating numbers, risen by age; the last third of the
 * lifetime fades to a dim color. Crits draw double-size and yellow
 * (bottom-anchored so the bigger glyphs grow upward, not into the monster).
 */
export function drawFloats(ctx: SpriteCanvas, pool: FloatingNumber[]): void {
  for (const f of pool) {
    if (!f.active) continue;
    const scale = f.crit ? CRIT_FLOAT_SCALE : FLOAT_SCALE;
    const text = f.crit ? `${f.text}!` : f.text;
    const faded = f.ageMs >= FLOAT_LIFE_MS * FLOAT_FADE_RATIO;
    const color = faded
      ? f.crit
        ? COLORS.orange
        : COLORS.steel
      : (f.color ?? (f.crit ? COLORS.yellow : COLORS.white));
    const rise = Math.round(FLOAT_RISE_PX * (f.crit ? CRIT_RISE_MULT : 1) * (f.ageMs / FLOAT_LIFE_MS));
    const x = Math.round(f.x - (textWidth(text) * scale) / 2);
    const y = f.y - rise - (scale - 1) * FONT_H;
    // 1-px void outline (4 offsets) under the glyphs: numbers stay readable over any art.
    for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
      drawScaledText(ctx, text, x + ox, y + oy, scale, COLORS.void);
    }
    drawScaledText(ctx, text, x, y, scale, color);
  }
}

/** Draw the active fever state directly above the hero, with a dark outline. */
export function drawFeverLabel(ctx: SpriteCanvas, cx: number, heroTop: number): void {
  const scale = 2;
  const x = Math.round(cx - (textWidth(FEVER_TEXT) * scale) / 2);
  const y = heroTop - 26;
  for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
    drawScaledText(ctx, FEVER_TEXT, x + ox, y + oy, scale, COLORS.void);
  }
  drawScaledText(ctx, FEVER_TEXT, x, y, scale, COLORS.yellow);
}

// ---------------------------------------------------------------------------
// "LEVEL UP!" banner (Manual M3): a centered double-size flash triggered by
// the engine's levelUp event. Single timer slot — a second level-up simply
// restarts it (no unbounded state).
// ---------------------------------------------------------------------------

/** Banner text — every glyph exists in font.ts's GLYPH_CHARS. */
export const LEVEL_UP_TEXT = 'LEVEL UP!';
export const FEVER_TEXT = 'FEVER!';
export const VICTORY_TEXT = 'VICTORY!';
export const DEFEAT_TEXT = 'DEFEAT';
/** Banner lifetime, ms. */
export const BANNER_MS = 1200;
/** Banner pixel scale. */
export const BANNER_SCALE = 2;
/** Flash cadence: the banner alternates yellow/white every interval. */
export const BANNER_FLASH_MS = 100;
/** Banner top edge, game pixels (clear of the HUD rows and the monster). */
export const BANNER_Y = 20;

/** The banner's single timer slot. */
export interface Banner {
  active: boolean;
  ageMs: number;
  text: string;
}

/** Fresh, inactive banner state. */
export function createBanner(): Banner {
  return { active: false, ageMs: 0, text: LEVEL_UP_TEXT };
}

/** (Re)start the banner — called on every levelUp event. */
export function showBanner(banner: Banner, text = LEVEL_UP_TEXT): void {
  banner.active = true;
  banner.ageMs = 0;
  banner.text = text;
}

/** Age the banner; it deactivates after BANNER_MS. */
export function tickBanner(banner: Banner, dtMs: number): void {
  if (!banner.active) {
    return;
  }
  banner.ageMs += dtMs;
  if (banner.ageMs >= BANNER_MS) {
    banner.active = false;
  }
}

/** Draw the flashing centered banner while it is active. */
export function drawBanner(ctx: SpriteCanvas, banner: Banner, viewW: number): void {
  if (!banner.active) {
    return;
  }
  const flashPhase = Math.floor(banner.ageMs / BANNER_FLASH_MS) % 2;
  const color = flashPhase === 0 ? COLORS.yellow : COLORS.white;
  const x = Math.round((viewW - textWidth(banner.text) * BANNER_SCALE) / 2);
  drawScaledText(ctx, banner.text, x, BANNER_Y, BANNER_SCALE, color);
}

// Companion collection — SPEC F32 (Assumptions 5/23/24/26; GAME_DESIGN_V2
// §4/§6). Pure TypeScript, zero imports of electron/DOM/node. Every export is
// total and never mutates its input: applyCollection returns fresh objects or
// an { error }, so the caller can apply it straight onto live engine state.

import { simulateBattle } from './battle.js';
import { monsterForIndex, sizeOf, typeOf } from './monsters.js';
import { monsterMaxHp } from './formulas.js';
import { effectivePower } from './types-chart.js';
import type { MonsterType } from './types-chart.js';
import type { BattleHeroes, Blow } from './battle.js';
import { heroBuffedPower } from './hero.js';
import type { HeroAction, HeroRoll } from './hero.js';
import type { Companion } from './save.js';
import type { Rng } from './rng.js';
import type { GameState, PvpResultAction } from './types.js';

/** A companion never levels past this (consume/reincarnate both cap here). */
export const COMPANION_MAX_LEVEL = 10;

/** How many companions fight together — field volley and PvP party (F61). */
export const PARTY_SIZE = 5;

/** Roster cap (save.ts keeps its own copy for parsing). */
export const ROSTER_CAP = 30;

/** Rebirth unlocks at this monster index (Assumption 5). */
export const REBIRTH_MIN_INDEX = 40;

/** Companion attack power (Assumption 24) — bigint, unbounded. */
export const companionPower = (c: Companion): bigint => {
  const base = monsterMaxHp(c.bossIndex) / 20n;
  return (base < 1n ? 1n : base) * BigInt(c.level) * 2n ** BigInt(c.stars);
};

/** Numeric part of a 'cN' id — the tie-breaker (same rule as parseSave). */
const idNum = (id: string): number => Number(id.replace(/\D/g, '') || 0);

/** Descending bigint comparator. */
const desc = (a: bigint, b: bigint): number => (a === b ? 0 : b > a ? 1 : -1);

/**
 * The PARTY_SIZE best companions against `enemyType` (F61): effective power
 * desc, ties → higher raw power → lower numeric id. Without a type the raw
 * power decides, which is what the PvP default `autoParty` wants.
 */
export function activeCompanions(
  cs: readonly Companion[],
  enemyType?: MonsterType,
  hero?: HeroRoll,
): Companion[] {
  const power = (c: Companion): bigint => heroBuffedPower(companionPower(c), typeOf(c.speciesId), hero);
  const effective = (c: Companion): bigint =>
    enemyType === undefined
      ? power(c)
      : effectivePower(power(c), typeOf(c.speciesId), enemyType);
  return [...cs]
    .sort(
      (a, b) =>
        desc(effective(a), effective(b)) ||
        desc(companionPower(a), companionPower(b)) ||
        idNum(a.id) - idNum(b.id),
    )
    .slice(0, PARTY_SIZE);
}

/** The PvP default party: the PARTY_SIZE strongest by raw power. */
export function autoParty(cs: readonly Companion[], hero?: HeroRoll): Companion[] {
  return activeCompanions(cs, undefined, hero);
}

/** `ids` resolved against `cs` in the given order; unknown/duplicate dropped. */
function resolveIds(cs: readonly Companion[], ids: readonly string[]): Companion[] {
  const party: Companion[] = [];
  for (const id of ids) {
    if (party.length >= PARTY_SIZE) break;
    const c = cs.find((x) => x.id === id);
    if (c && !party.includes(c)) party.push(c);
  }
  return party;
}

/** The manual PvP party; an empty result falls back to `autoParty` (F61). */
export function pvpParty(cs: readonly Companion[], ids: readonly string[], hero?: HeroRoll): Companion[] {
  const party = resolveIds(cs, ids);
  return party.length > 0 ? party : autoParty(cs, hero);
}

/** Draw order of a party: biggest first (back row), ties keep party order. */
export function partyOrder(party: readonly Companion[]): Companion[] {
  return [...party].sort((a, b) => sizeOf(b.speciesId) - sizeOf(a.speciesId));
}

/**
 * Events produced here (GAME_DESIGN_V2 §6). T28 folds both variants into the
 * `GameEvent` union in types.ts; every other action returns no events.
 * ponytail: declared locally until then — types.ts is owned by T26/T28/T29.
 */
export type CollectionEvent =
  | { type: 'rebirth'; souls: number }
  | { type: 'pvpResolved'; won: boolean; stolen: Companion | null; lostId: string | null };

/** Every roster/prestige operation the menu and the net layer can request. */
export type CollectionAction =
  | HeroAction
  | { type: 'consume'; targetId: string; foodId: string }
  | { type: 'fuse'; aId: string; bId: string }
  | { type: 'reincarnate'; id: string }
  | { type: 'sacrifice'; id: string }
  | { type: 'rebirth' }
  | { type: 'addCompanion'; companion: Companion }
  | { type: 'removeCompanions'; ids: string[] }
  | { type: 'setPvpParty'; ids: string[] }
  | PvpResultAction;

export type CollectionResult =
  | { state: GameState; events: CollectionEvent[] }
  | { error: string };

/** Fresh roster: `dropIds` removed, `editId` replaced by `edit(c)`, rest copied. */
function reroster(
  cs: readonly Companion[],
  dropIds: readonly string[],
  editId?: string,
  edit?: (c: Companion) => Companion,
): Companion[] {
  return cs
    .filter((c) => !dropIds.includes(c.id))
    .map((c) => (edit && c.id === editId ? edit(c) : { ...c }));
}

/** Fresh state: nothing of `state` is shared with the result. */
function next(
  state: Readonly<GameState>,
  companions: Companion[],
  patch: Partial<GameState> = {},
  events: CollectionEvent[] = [],
): CollectionResult {
  return {
    state: {
      ...state,
      items: { ...state.items },
      monster: { ...state.monster },
      companions,
      ...patch,
    },
    events,
  };
}

/** Push `c` re-minted as `c${nextCompanionId}`; null when the roster is full. */
function minted(
  companions: Companion[],
  nextCompanionId: number,
  c: Companion,
): Companion | null {
  if (companions.length >= ROSTER_CAP) return null;
  const fresh: Companion = { ...c, id: `c${nextCompanionId}` };
  companions.push(fresh);
  return fresh;
}

/**
 * Apply one lifecycle action (Assumption 26). Total: an unknown action type,
 * an unknown/duplicate companion id or an unmet precondition yields
 * `{ error }` and the caller keeps its state; success yields a brand-new
 * state plus the events of GAME_DESIGN_V2 §6.
 */
export function applyCollection(
  state: Readonly<GameState>,
  action: CollectionAction,
): CollectionResult {
  const cs = state.companions;
  const find = (id: string): Companion | undefined => cs.find((c) => c.id === id);

  switch (action.type) {
    case 'consume': {
      const target = find(action.targetId);
      const food = find(action.foodId);
      if (!target || !food || target.id === food.id) return { error: 'consume: bad ids' };
      return next(
        state,
        reroster(cs, [food.id], target.id, (c) => ({
          ...c,
          level: Math.min(COMPANION_MAX_LEVEL, c.level + 1 + food.stars),
        })),
      );
    }
    case 'fuse': {
      const a = find(action.aId);
      const b = find(action.bId);
      if (!a || !b || a.id === b.id) return { error: 'fuse: bad ids' };
      if (a.speciesId !== b.speciesId || a.stars !== b.stars) {
        return { error: 'fuse: needs the same species and stars' };
      }
      return next(
        state,
        reroster(cs, [b.id], a.id, (c) => ({
          ...c,
          bossIndex: Math.max(a.bossIndex, b.bossIndex),
          level: 1,
          stars: c.stars + 1,
        })),
      );
    }
    case 'reincarnate': {
      const c = find(action.id);
      if (!c) return { error: 'reincarnate: unknown id' };
      if (c.level !== COMPANION_MAX_LEVEL) return { error: 'reincarnate: needs max level' };
      return next(
        state,
        reroster(cs, [], c.id, (x) => ({ ...x, level: 1, stars: x.stars + 1 })),
      );
    }
    case 'sacrifice': {
      const c = find(action.id);
      if (!c) return { error: 'sacrifice: unknown id' };
      return next(state, reroster(cs, [c.id]), { souls: state.souls + 1 + c.stars });
    }
    case 'rebirth': {
      if (state.monster.index < REBIRTH_MIN_INDEX) {
        return { error: `rebirth: needs monster index ${REBIRTH_MIN_INDEX}` };
      }
      const souls = state.souls + Math.floor(state.monster.index / 8);
      const first = monsterForIndex(0);
      return next(
        state,
        reroster(cs, []),
        {
          level: 1,
          xp: 0,
          monster: first,
          monsterHp: first.maxHp,
          souls,
          rebirths: state.rebirths + 1,
        },
        [{ type: 'rebirth', souls }],
      );
    }
    case 'addCompanion': {
      const companions = reroster(cs, []);
      if (!minted(companions, state.nextCompanionId, action.companion)) {
        return { error: 'addCompanion: roster is full' };
      }
      return next(state, companions, { nextCompanionId: state.nextCompanionId + 1 });
    }
    case 'removeCompanions':
      return next(state, reroster(cs, action.ids));
    case 'setPvpParty':
      // Never an error and no event: an all-unknown list just empties it.
      return next(state, reroster(cs, []), {
        pvpParty: resolveIds(cs, action.ids).map((c) => c.id),
      });
    case 'pvpResult': {
      const companions = reroster(cs, action.lostId === null ? [] : [action.lostId]);
      // A steal into a full roster is void, never an error (Assumption 23).
      const stolen = action.stolen && minted(companions, state.nextCompanionId, action.stolen);
      return next(
        state,
        companions,
        { nextCompanionId: state.nextCompanionId + (stolen ? 1 : 0) },
        [
          {
            type: 'pvpResolved',
            won: action.won,
            stolen: stolen ?? null,
            lostId: action.lostId,
          },
        ],
      );
    }
    default:
      return { error: 'unknown action' };
  }
}

/** Chance an attacking win also carries a companion home (GAME_DESIGN_V3 §5). */
export const STEAL_CHANCE = 0.15;

/**
 * Resolve one asynchronous PvP exchange (SPEC F37; GAME_DESIGN_V3 §5). The
 * verdict and the blow list come from the seedless `simulateBattle`; the rng
 * only decides the loot. Shared byte-for-byte with the server, which calls it
 * with `mulberry32(seed)` and moves `moved` between the stored rosters — so
 * exactly 2 draws happen per call, the victim draw included even when nobody
 * can be stolen, and the client can replay the same match from the seed.
 * Only the attacker ever steals: a losing attacker keeps its whole roster.
 * ponytail: `attackerRosterSize` defaults to the party size so the v2 3-arg
 * call still compiles; T60 passes the real roster length.
 */
export function resolvePvp(
  attacker: readonly Companion[],
  defender: readonly Companion[],
  rng: Rng,
  attackerRosterSize = attacker.length,
  heroes: BattleHeroes = {},
): { attackerWon: boolean; moved: Companion | null; blows: Blow[] } {
  const { attackerWon, blows } = simulateBattle(attacker, defender, heroes);
  const stealRoll = rng.next() < STEAL_CHANCE;
  const victim = defender[Math.floor(rng.next() * defender.length)] ?? null;
  return {
    attackerWon,
    moved: attackerWon && stealRoll && attackerRosterSize < ROSTER_CAP ? victim : null,
    blows,
  };
}

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/** 3 different elements; top unlocked rank guaranteed; unowned forms preferred. */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    let pool = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type) && (i !== 0 || f.rank === rank));
    const unseen = pool.filter((f) => !hero.collection.some((r) => r.formId === f.id));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    if (killed.boss && rng.next() < CAPTURE_CHANCE && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

// Save schema & tolerant parsing — SPEC F10/F29, Assumptions 7/21. Pure
// TypeScript, zero imports of electron/DOM/node. The app must never fail to
// boot because of a bad save: parseSave() NEVER throws — junk, missing and
// wrong-typed fields fall back per-field to DEFAULT_SAVE values. Disk always
// holds v3; older files are migrated on the way in (upgradeSave).

import { bigField } from './bignum.js';
import { monsterMaxHp } from './formulas.js';
import { isSpeciesId, SPECIES_IDS } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { parseHeroProgress } from './hero.js';
import type { HeroProgress } from './hero.js';

/** Roster cap (GAME_DESIGN_V2 §2/§3); collection.ts owns the gameplay copy. */
const ROSTER_CAP = 30;

/** PvP party cap (GAME_DESIGN_V3 §3/§4); collection.ts owns the gameplay copy. */
const PARTY_CAP = 5;

/** A captured boss (GAME_DESIGN_V2 §2). Ids are minted from nextCompanionId. */
export interface Companion {
  /** 'c1', 'c2' … — deterministic, never a uuid. */
  id: string;
  /** SpeciesId of the captured boss. */
  speciesId: string;
  /** Global monster index it was captured at → base power. */
  bossIndex: number;
  /** 1..COMPANION_MAX_LEVEL (10). */
  level: number;
  stars: number;
}

/** Legacy save shape (v1). Accepted as input, never written. */
export interface SaveFileV1 {
  version: 1;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  monsterHp: number;
}

/**
 * Persisted save-file schema, version 2. The engine's toSave() emits exactly
 * this shape; createEngine(save) resumes from it (SPEC F11/F29).
 */
export interface SaveFileV2 {
  version: 2;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  /** Decimal digits, ≥ '1' — HP is unbounded (SPEC F30). */
  monsterHp: string;
  /** Captured bosses, at most ROSTER_CAP entries. */
  companions: Companion[];
  nextCompanionId: number;
  souls: number;
  rebirths: number;
  /** Deepest monsterIndex ever reached. */
  bestIndex: number;
}

/**
 * Persisted save-file schema, version 3: v2 plus the manually picked PvP-only
 * party (GAME_DESIGN_V3 §3). Empty = the auto party is used.
 */
export interface SaveFileV3 extends Omit<SaveFileV2, 'version'> {
  version: 3;
  /** Randomly selected current species; absent in legacy saves. */
  monsterSpeciesId?: SpeciesId;
  /** Companion ids, at most PARTY_CAP, all present in `companions`. */
  pvpParty: string[];
  /** Additive v0.4 extension; v1–v3 saves retain their progress unchanged. */
  hero?: HeroProgress;
}

/** The current schema. */
export type SaveFile = SaveFileV3;

/** Fresh-game values; also the per-field fallback for junk input. */
export const DEFAULT_SAVE: Readonly<SaveFileV3> = Object.freeze({
  version: 3 as const,
  level: 1,
  xp: 0,
  killCount: 0,
  coins: 0,
  items: Object.freeze({}) as Record<string, number>,
  monsterIndex: 0,
  monsterHp: String(monsterMaxHp(0)),
  companions: Object.freeze([] as Companion[]) as Companion[],
  nextCompanionId: 1,
  souls: 0,
  rebirths: 0,
  bestIndex: 0,
  pvpParty: Object.freeze([] as string[]) as string[],
});

/**
 * Migrate a well-formed save to v3. v1 had no roster, souls or best depth;
 * v2 had no PvP party.
 */
export function upgradeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): SaveFileV3 {
  if (save.version === 3) return save;
  if (save.version === 2) return { ...save, version: 3, pvpParty: [] };
  return {
    version: 3,
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monsterIndex: save.monsterIndex,
    monsterHp: String(Math.max(1, Math.floor(save.monsterHp))),
    companions: [],
    nextCompanionId: 1,
    souls: 0,
    rebirths: 0,
    bestIndex: save.monsterIndex,
    pvpParty: [],
  };
}

/**
 * Stable JSON: fixed top-level key order, items keys sorted, companions in
 * array order with fixed key order. Serializing the same logical save always
 * yields byte-identical text. Older input is upgraded first.
 */
export function serializeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): string {
  const v3 = upgradeSave(save);
  const items: Record<string, number> = {};
  for (const id of Object.keys(v3.items).sort()) {
    items[id] = v3.items[id] ?? 0;
  }
  return JSON.stringify({
    version: 3,
    level: v3.level,
    xp: v3.xp,
    killCount: v3.killCount,
    coins: v3.coins,
    items,
    monsterIndex: v3.monsterIndex,
    monsterSpeciesId: v3.monsterSpeciesId,
    monsterHp: v3.monsterHp,
    companions: v3.companions.map((c) => ({
      id: c.id,
      speciesId: c.speciesId,
      bossIndex: c.bossIndex,
      level: c.level,
      stars: c.stars,
    })),
    nextCompanionId: v3.nextCompanionId,
    souls: v3.souls,
    rebirths: v3.rebirths,
    bestIndex: v3.bestIndex,
    pvpParty: v3.pvpParty,
    hero: parseHeroProgress(v3.hero),
  });
}

/** Finite number → floored int clamped to `min`; anything else → fallback. */
function intField(value: unknown, fallback: number, min: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
  return Math.max(min, Math.floor(value));
}

/** Integer in [min, max] — the companion fields have no fallback, they drop. */
function isInt(value: unknown, min: number, max = Number.MAX_SAFE_INTEGER): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Keep only entries whose count is a finite number that floors to ≥ 1. */
function itemsField(value: unknown): Record<string, number> {
  const items: Record<string, number> = {};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return items;
  }
  for (const [id, count] of Object.entries(value)) {
    if (typeof count === 'number' && Number.isFinite(count) && Math.floor(count) >= 1) {
      items[id] = Math.floor(count);
    }
  }
  return items;
}

/**
 * Keep only fully valid companions (GAME_DESIGN_V2 §2): a bad entry is
 * dropped, it never defaults — a half-made companion would be worse than
 * none. Duplicate ids: first wins. At most ROSTER_CAP kept.
 */
function companionsField(value: unknown): Companion[] {
  const kept: Companion[] = [];
  if (!Array.isArray(value)) return kept;
  const seen = new Set<string>();
  for (const raw of value) {
    if (kept.length >= ROSTER_CAP) break;
    if (typeof raw !== 'object' || raw === null) continue;
    const c = raw as Record<string, unknown>;
    const id = c['id'];
    const speciesId = c['speciesId'];
    if (typeof id !== 'string' || id === '' || seen.has(id)) continue;
    if (typeof speciesId !== 'string' || !(SPECIES_IDS as readonly string[]).includes(speciesId)) {
      continue;
    }
    if (!isInt(c['bossIndex'], 0) || !isInt(c['level'], 1, 10) || !isInt(c['stars'], 0)) continue;
    seen.add(id);
    kept.push({ id, speciesId, bossIndex: c['bossIndex'], level: c['level'], stars: c['stars'] });
  }
  return kept;
}

/**
 * Keep only ids that are really on the parsed roster (a party pointing at a
 * consumed companion would resurrect it), deduped first-wins, PARTY_CAP kept.
 */
function pvpPartyField(value: unknown, companions: Companion[]): string[] {
  if (!Array.isArray(value)) return [];
  const ids = new Set(companions.map((c) => c.id));
  return [...new Set(value.filter((id): id is string => typeof id === 'string' && ids.has(id)))]
    .slice(0, PARTY_CAP);
}

/**
 * Tolerant parse of untrusted save data (SPEC F10/F29). Accepts anything —
 * pre-parsed JSON values (what main's load-state hands over) or raw JSON
 * text — and NEVER throws. Every invalid field independently falls back to
 * its DEFAULT_SAVE value; the input `version` is ignored (the shape decides)
 * and the output is always v3. Range clamping beyond that (e.g. monsterHp vs
 * the monster's maxHp) is the engine's job. Always returns fresh objects.
 */
export function parseSave(raw: unknown): SaveFileV3 {
  let value: unknown = raw;
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      value = null;
    }
  }
  const record: Record<string, unknown> =
    typeof value === 'object' && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};
  const companions = companionsField(record['companions']);
  const hero = parseHeroProgress(record['hero']);
  const species = record['monsterSpeciesId'];
  // Re-minting must never collide with an id already on the roster.
  let nextCompanionId = intField(record['nextCompanionId'], DEFAULT_SAVE.nextCompanionId, 1);
  for (const c of companions) {
    nextCompanionId = Math.max(nextCompanionId, Number(c.id.replace(/\D/g, '') || 0) + 1);
  }
  return {
    version: 3,
    level: intField(record['level'], DEFAULT_SAVE.level, 1),
    xp: intField(record['xp'], DEFAULT_SAVE.xp, 0),
    killCount: intField(record['killCount'], DEFAULT_SAVE.killCount, 0),
    coins: intField(record['coins'], DEFAULT_SAVE.coins, 0),
    items: itemsField(record['items']),
    monsterIndex: intField(record['monsterIndex'], DEFAULT_SAVE.monsterIndex, 0),
    ...(typeof species === 'string' && isSpeciesId(species) ? { monsterSpeciesId: species } : {}),
    monsterHp: (bigField(record['monsterHp']) ?? DEFAULT_SAVE.monsterHp).replace(/^0$/, '1'),
    companions,
    nextCompanionId,
    souls: intField(record['souls'], DEFAULT_SAVE.souls, 0),
    rebirths: intField(record['rebirths'], DEFAULT_SAVE.rebirths, 0),
    bestIndex: intField(record['bestIndex'], DEFAULT_SAVE.bestIndex, 0),
    pvpParty: pvpPartyField(record['pvpParty'], companions),
    ...(hero ? { hero } : {}),
  };
}

// HUD painting (SPEC F21 + T14/T15 presentation): boxed monster HP bar,
// top-left `LV n` + XP bar, top-right kill/coin counters (with a collection
// pop flash), the pooled floating-damage-number system — numbers rise 8px
// and fade over 600ms; crits draw double-size and yellow (Manual M2) — and
// the flashing "LEVEL UP!" banner (Manual M3).
// DOM-free on purpose — everything draws through SpriteCanvas so the tests
// run under vitest's node environment (same pattern as sprites/sprite.ts).

import { ratio, xpToNext } from '../core/index.js';
import type { Effectiveness, GameState } from '../core/index.js';
import { heroReady } from '../core/hero.js';
import {
  COLORS,
  drawSprite,
  drawText,
  FONT_ADVANCE,
  FONT_H,
  FONT_W,
  fontSprite,
  glyphIndex,
  itemSprites,
  textWidth,
  TRANSPARENT,
} from './sprites/index.js';
import type { SpriteCanvas } from './sprites/index.js';

/** Gap between HUD chrome and the canvas edges, in game pixels. */
export const HUD_MARGIN = 2;
/** Keep counters below the drag strip, closer to the field. */
export const COUNTER_TOP = 16;
/** XP progress bar box size (top-left, under the LV text). */
export const XP_BAR_W = 40;
export const XP_BAR_H = 4;

/**
 * Boxed meter: 1px steel frame, void interior, proportional fill. A non-zero
 * ratio always shows at least 1px of fill; out-of-range/non-finite ratios
 * are clamped so a bad value can never paint outside the box.
 */
export function drawMeter(
  ctx: SpriteCanvas,
  x: number,
  y: number,
  w: number,
  h: number,
  ratio: number,
  fillColor: string,
): void {
  ctx.fillStyle = COLORS.steel;
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(x + 1, y + 1, w - 2, h - 2);
  const clamped = Number.isFinite(ratio) ? Math.min(1, Math.max(0, ratio)) : 0;
  const fill = clamped === 0 ? 0 : Math.max(1, Math.round((w - 2) * clamped));
  if (fill > 0) {
    ctx.fillStyle = fillColor;
    ctx.fillRect(x + 1, y + 1, fill, h - 2);
  }
}

/** Boxed red HP bar (drawn above the monster). */
export function drawHpBar(
  ctx: SpriteCanvas,
  x: number,
  y: number,
  w: number,
  h: number,
  hp: bigint,
  maxHp: bigint,
): void {
  drawMeter(ctx, x, y, w, h, ratio(hp, maxHp), COLORS.red);
}

/**
 * `LV n` text plus the XP progress bar, floating above the hero's head
 * (Assumption 17): `cx` is the hero's horizontal center, `bottom` sits just
 * above the hero's top row — the bar hugs the head, the label rides above it.
 */
export function drawLevelHud(
  ctx: SpriteCanvas,
  state: Readonly<GameState>,
  cx: number,
  bottom: number,
): void {
  const barX = Math.round(cx - XP_BAR_W / 2);
  const barY = bottom - XP_BAR_H;
  drawMeter(ctx, barX, barY, XP_BAR_W, XP_BAR_H, state.xp / xpToNext(state.level), COLORS.cyan);
  const label = `LV ${String(state.level)}`;
  drawText(ctx, label, Math.round(cx - textWidth(label) / 2), barY - FONT_H - 2);
  if (heroReady(state.level, state.hero)) {
    const ready = 'REBIRTH READY';
    drawText(ctx, ready, Math.round(cx - textWidth(ready) / 2), barY - 2 * (FONT_H + 2), { color: COLORS.yellow });
  }
}

/** 5×5 skull marker for the kill counter — HUD chrome, drawn directly. */
function drawSkullIcon(ctx: SpriteCanvas, x: number, y: number): void {
  ctx.fillStyle = COLORS.white;
  ctx.fillRect(x, y, 5, 3); // cranium
  ctx.fillRect(x + 1, y + 3, 3, 2); // jaw
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(x + 1, y + 1, 1, 1); // left eye socket
  ctx.fillRect(x + 3, y + 1, 1, 1); // right eye socket
  ctx.fillRect(x + 2, y + 4, 1, 1); // tooth gap
}

/** How long the coin counter stays "popped" after a drop arrives, ms. */
export const COUNTER_POP_MS = 150;

/**
 * Top-right HUD: skull × killCount row, coin × coins row (right-aligned).
 * While `coinPop` is set (a collected drop just arrived, T15) the coin row
 * pops: the count flashes white and the icon lifts one pixel.
 */
export function drawCounters(
  ctx: SpriteCanvas,
  state: Readonly<GameState>,
  viewW: number,
  coinPop = false,
): void {
  const kills = String(state.killCount);
  const killsX = viewW - HUD_MARGIN - textWidth(kills);
  drawText(ctx, kills, killsX, COUNTER_TOP);
  drawSkullIcon(ctx, killsX - 7, COUNTER_TOP);

  const coins = String(state.coins);
  const coinsX = viewW - HUD_MARGIN - textWidth(coins);
  drawText(ctx, coins, coinsX, COUNTER_TOP + FONT_H + 2, {
    color: coinPop ? COLORS.white : COLORS.yellow,
  });
  const iconY = COUNTER_TOP + FONT_H + (coinPop ? 0 : 1);
  drawSprite(ctx, itemSprites.coin, 0, coinsX - 8, iconY);
}

/** One pooled floating damage number. Slots are reused, never reallocated. */
export interface FloatingNumber {
  active: boolean;
  /** Horizontal center of the text, in game pixels. */
  x: number;
  /** Spawn baseline; the number rises FLOAT_RISE_PX over its lifetime. */
  y: number;
  text: string;
  crit: boolean;
  ageMs: number;
  /** Fresh-phase colour override (companion floats, F64); crit rules if unset. */
  color?: string;
}

/** Fixed pool size — key-mashing can never grow an unbounded array. */
export const FLOAT_POOL_SIZE = 16;
/** Lifetime of one floating number, ms. */
export const FLOAT_LIFE_MS = 600;
/** Total rise over the lifetime, game pixels. */
export const FLOAT_RISE_PX = 14;
/** Age fraction past which a float draws in its dim fade color. */
export const FLOAT_FADE_RATIO = 2 / 3;
/** Pixel scale of normal damage numbers (user change 2026-09-06: readable 2x glyphs with a 1-px outline). */
export const FLOAT_SCALE = 2;
/** Pixel scale of crit damage numbers (Manual M2: crits show larger — 3x, yellow, with a '!'). */
export const CRIT_FLOAT_SCALE = 3;
/** Crits rise this much further than normal floats (same lifetime, punchier). */
export const CRIT_RISE_MULT = 1.5;

export function floatColor(effectiveness: Effectiveness): string {
  return effectiveness === 'super'
    ? COLORS.yellow
    : effectiveness === 'weak'
      ? COLORS.steel
      : COLORS.white;
}

/** Pre-allocate a pool of inactive floating-number slots. */
export function createFloatPool(size: number = FLOAT_POOL_SIZE): FloatingNumber[] {
  return Array.from({ length: size }, () => ({
    active: false,
    x: 0,
    y: 0,
    text: '',
    crit: false,
    ageMs: 0,
  }));
}

/** Activate a slot: the first inactive one, else recycle the oldest active. */
export function spawnFloat(
  pool: FloatingNumber[],
  x: number,
  y: number,
  text: string,
  crit: boolean,
  color?: string,
): void {
  let slot = pool.find((f) => !f.active);
  if (slot === undefined) {
    for (const f of pool) {
      if (slot === undefined || f.ageMs > slot.ageMs) {
        slot = f;
      }
    }
  }
  if (slot === undefined) {
    return; // zero-size pool
  }
  slot.active = true;
  slot.x = x;
  slot.y = y;
  slot.text = text;
  slot.crit = crit;
  slot.color = color;
  slot.ageMs = 0;
}

/** Age every active slot; slots past FLOAT_LIFE_MS deactivate. */
export function tickFloats(pool: FloatingNumber[], dtMs: number): void {
  for (const f of pool) {
    if (!f.active) {
      continue;
    }
    f.ageMs += dtMs;
    if (f.ageMs >= FLOAT_LIFE_MS) {
      f.active = false;
    }
  }
}

/**
 * drawText at an integer pixel scale: every glyph pixel becomes a
 * scale×scale rect. Local to the HUD — the sprite/font modules stay
 * 1px-based (their data is covered by the T11 integrity sweep).
 */
function drawScaledText(
  ctx: SpriteCanvas,
  text: string,
  x: number,
  y: number,
  scale: number,
  color: string,
): void {
  if (scale === 1) {
    drawText(ctx, text, x, y, { color });
    return;
  }
  for (let i = 0; i < text.length; i++) {
    const rows = fontSprite.frames[glyphIndex(text.charAt(i))];
    if (rows === undefined) {
      continue; // unknown chars still advance a cell — stable layout
    }
    for (let ry = 0; ry < FONT_H; ry++) {
      const row = rows[ry];
      if (row === undefined) {
        continue;
      }
      for (let rx = 0; rx < FONT_W; rx++) {
        const ch = row.charAt(rx);
        if (ch === TRANSPARENT || ch === '') {
          continue;
        }
        ctx.fillStyle = color;
        ctx.fillRect(x + (i * FONT_ADVANCE + rx) * scale, y + ry * scale, scale, scale);
      }
    }
  }
}

/**
 * Draw active floating numbers, risen by age; the last third of the
 * lifetime fades to a dim color. Crits draw double-size and yellow
 * (bottom-anchored so the bigger glyphs grow upward, not into the monster).
 */
export function drawFloats(ctx: SpriteCanvas, pool: FloatingNumber[]): void {
  for (const f of pool) {
    if (!f.active) continue;
    const scale = f.crit ? CRIT_FLOAT_SCALE : FLOAT_SCALE;
    const text = f.crit ? `${f.text}!` : f.text;
    const faded = f.ageMs >= FLOAT_LIFE_MS * FLOAT_FADE_RATIO;
    const color = faded
      ? f.crit
        ? COLORS.orange
        : COLORS.steel
      : (f.color ?? (f.crit ? COLORS.yellow : COLORS.white));
    const rise = Math.round(FLOAT_RISE_PX * (f.crit ? CRIT_RISE_MULT : 1) * (f.ageMs / FLOAT_LIFE_MS));
    const x = Math.round(f.x - (textWidth(text) * scale) / 2);
    const y = f.y - rise - (scale - 1) * FONT_H;
    // 1-px void outline (4 offsets) under the glyphs: numbers stay readable over any art.
    for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
      drawScaledText(ctx, text, x + ox, y + oy, scale, COLORS.void);
    }
    drawScaledText(ctx, text, x, y, scale, color);
  }
}

/** Draw the active fever state directly above the hero, with a dark outline. */
export function drawFeverLabel(ctx: SpriteCanvas, cx: number, heroTop: number): void {
  const scale = 2;
  const x = Math.round(cx - (textWidth(FEVER_TEXT) * scale) / 2);
  const y = heroTop - 26;
  for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
    drawScaledText(ctx, FEVER_TEXT, x + ox, y + oy, scale, COLORS.void);
  }
  drawScaledText(ctx, FEVER_TEXT, x, y, scale, COLORS.yellow);
}

// ---------------------------------------------------------------------------
// "LEVEL UP!" banner (Manual M3): a centered double-size flash triggered by
// the engine's levelUp event. Single timer slot — a second level-up simply
// restarts it (no unbounded state).
// ---------------------------------------------------------------------------

/** Banner text — every glyph exists in font.ts's GLYPH_CHARS. */
export const LEVEL_UP_TEXT = 'LEVEL UP!';
export const FEVER_TEXT = 'FEVER!';
export const VICTORY_TEXT = 'VICTORY!';
export const DEFEAT_TEXT = 'DEFEAT';
/** Banner lifetime, ms. */
export const BANNER_MS = 1200;
/** Banner pixel scale. */
export const BANNER_SCALE = 2;
/** Flash cadence: the banner alternates yellow/white every interval. */
export const BANNER_FLASH_MS = 100;
/** Banner top edge, game pixels (clear of the HUD rows and the monster). */
export const BANNER_Y = 20;

/** The banner's single timer slot. */
export interface Banner {
  active: boolean;
  ageMs: number;
  text: string;
}

/** Fresh, inactive banner state. */
export function createBanner(): Banner {
  return { active: false, ageMs: 0, text: LEVEL_UP_TEXT };
}

/** (Re)start the banner — called on every levelUp event. */
export function showBanner(banner: Banner, text = LEVEL_UP_TEXT): void {
  banner.active = true;
  banner.ageMs = 0;
  banner.text = text;
}

/** Age the banner; it deactivates after BANNER_MS. */
export function tickBanner(banner: Banner, dtMs: number): void {
  if (!banner.active) {
    return;
  }
  banner.ageMs += dtMs;
  if (banner.ageMs >= BANNER_MS) {
    banner.active = false;
  }
}

/** Draw the flashing centered banner while it is active. */
export function drawBanner(ctx: SpriteCanvas, banner: Banner, viewW: number): void {
  if (!banner.active) {
    return;
  }
  const flashPhase = Math.floor(banner.ageMs / BANNER_FLASH_MS) % 2;
  const color = flashPhase === 0 ? COLORS.yellow : COLORS.white;
  const x = Math.round((viewW - textWidth(banner.text) * BANNER_SCALE) / 2);
  drawScaledText(ctx, banner.text, x, BANNER_Y, BANNER_SCALE, color);
}

// Real engine, injected RNG/clock, no wall time or input hooks. A simulation
// measures pacing; it cannot certify that a human finds the game enjoyable.
import { writeFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { createEngine, heroReady, mulberry32 } from '../src/core/index.js';

type Profile = 'active' | 'idle' | 'intermittent';
interface Sample { minutes: number; profile: Profile; seed: number; kills: number; firstOfferSec: number | null;
  reincarnations: number; collected: number; coins: number; companions: number; longestKillGapSec: number;
  /** v0.4 expedition payoff: full-roster releases, and how many were the first card unseen. */
  released: number; souls: number; unseenFirstCards: number; offers: number }

function simulate(profile: Profile, seed: number): Sample[] {
  const engine = createEngine(null, mulberry32(seed));
  const result: Sample[] = [];
  let firstOfferSec: number | null = null;
  let lastKill = 0;
  let longestKillGapSec = 0;
  let released = 0;
  let unseenFirstCards = 0;
  let offers = 0;
  for (let sec = 1; sec <= 1800; sec++) {
    // All profiles get a two-minute onboarding. Idle then stops input;
    // intermittent works 15 seconds per minute; active inputs twice a second.
    const inputs = sec <= 120 || profile === 'active' || (profile === 'intermittent' && sec % 60 < 15) ? 2 : 0;
    let killed = false;
    for (let i = 0; i < inputs; i++) {
      const hit = engine.attack('keyboard');
      killed = hit.some((e) => e.type === 'monsterKilled') || killed;
      released += hit.filter((e) => e.type === 'companionReleased').length;
    }
    // Do not short-circuit engine steps when an earlier input killed.
    const events = engine.tick(1000);
    killed = events.some((e) => e.type === 'monsterKilled') || killed;
    released += events.filter((e) => e.type === 'companionReleased').length;
    if (killed) {
      longestKillGapSec = Math.max(longestKillGapSec, sec - lastKill);
      lastKill = sec;
    }
    const state = engine.getState();
    if (heroReady(state.level, state.hero)) {
      firstOfferSec ??= sec;
      engine.apply({ type: 'heroOffer' });
      const hero = engine.getState().hero!;
      // Choose the first card, without any gold rerolls — the same policy the
      // v0.4 baseline used, so before/after numbers stay comparable.
      offers++;
      if (!hero.collection.some((r) => r.formId === hero.choices[0]!.formId)) unseenFirstCards++;
      engine.apply({ type: 'heroChoose', formId: hero.choices[0]!.formId, offerSerial: hero.offerSerial });
    }
    if ([300, 900, 1800].includes(sec)) {
      const current = engine.getState();
      result.push({ minutes: sec / 60, profile, seed, kills: current.killCount,
        firstOfferSec, reincarnations: current.hero?.reincarnations ?? 0,
        collected: current.hero?.collection.length ?? 0, coins: current.coins,
        companions: current.companions.length,
        longestKillGapSec: Math.max(longestKillGapSec, sec - lastKill),
        released, souls: current.souls, unseenFirstCards, offers });
    }
  }
  return result;
}

describe('v0.4 deterministic pacing playtest', () => {
  it('checks 100 seeds across active, warm-idle and intermittent play at 5/15/30 minutes', () => {
    const samples = (['active', 'idle', 'intermittent'] as const).flatMap((profile) =>
      Array.from({ length: 100 }, (_, i) => {
        const sample = simulate(profile, i + 1);
        if (process.env.DESMON_BALANCE_REPORT && (i + 1) % 25 === 0) process.stdout.write(`${profile}: ${i + 1}/100 seeds\n`);
        return sample;
      }).flat());
    const quantiles = (values: number[]) => {
      const sorted = [...values].sort((a, b) => a - b);
      return { p10: sorted[Math.floor((sorted.length - 1) * .1)]!, p50: sorted[Math.floor((sorted.length - 1) * .5)]!, p90: sorted[Math.floor((sorted.length - 1) * .9)]! };
    };
    const scenarios = (['active', 'idle', 'intermittent'] as const).flatMap((profile) => [5, 15, 30].map((minutes) => {
      const rows = samples.filter((s) => s.profile === profile && s.minutes === minutes);
      return { profile, minutes, samples: rows.length,
        firstOfferReached: rows.filter((r) => r.firstOfferSec !== null).length,
        firstOfferSec: quantiles(rows.flatMap((r) => r.firstOfferSec === null ? [] : [r.firstOfferSec])),
        kills: quantiles(rows.map((r) => r.kills)), reincarnations: quantiles(rows.map((r) => r.reincarnations)),
        collected: quantiles(rows.map((r) => r.collected)), coins: quantiles(rows.map((r) => r.coins)),
        longestKillGapSec: quantiles(rows.map((r) => r.longestKillGapSec)),
        released: quantiles(rows.map((r) => r.released)), souls: quantiles(rows.map((r) => r.souls)),
        unseenFirstCardRatio: rows.reduce((sum, r) => sum + (r.offers === 0 ? 1 : r.unseenFirstCards / r.offers), 0) / rows.length,
        fullRosters: rows.filter((r) => r.companions === 30).length };
    }));
    const report = { version: '0.4.0', kind: 'simulated-not-human', seeds: '1..100',
      inputModel: '2 inputs/s; 120s onboarding, then idle=0/s; intermittent=15s/min; choose first offer, no rerolls, no companion management',
      scenarios, rawSamples: samples };
    if (process.env.DESMON_BALANCE_REPORT) writeFileSync(process.env.DESMON_BALANCE_REPORT, JSON.stringify(report, null, 2) + '\n');
    expect(samples).toHaveLength(900);
    expect(samples.every((s) => s.coins >= 0 && s.collected <= 50 && s.companions <= 30)).toBe(true);
    const active = scenarios.find((s) => s.profile === 'active' && s.minutes === 5)!;
    expect(active.firstOfferReached).toBe(100);
    expect(active.firstOfferSec.p90).toBeLessThanOrEqual(300);
    for (const profile of ['active', 'idle', 'intermittent']) {
      const early = scenarios.find((s) => s.profile === profile && s.minutes === 5)!;
      const late = scenarios.find((s) => s.profile === profile && s.minutes === 30)!;
      expect(late.kills.p50).toBeGreaterThan(early.kills.p50);
      expect(late.reincarnations.p50).toBeGreaterThan(early.reincarnations.p50);
    }
    // H4 — the v0.4 expedition payoff may not move the measured pacing more
    // than the ±5% budget the design was approved under (baseline: first offer
    // 79s, active 30 min 1,238 kills / 15 reincarnations).
    const active30 = scenarios.find((s) => s.profile === 'active' && s.minutes === 30)!;
    expect(active.firstOfferSec.p50).toBeGreaterThanOrEqual(74);
    expect(active.firstOfferSec.p50).toBeLessThanOrEqual(84);
    expect(active30.kills.p50).toBeGreaterThanOrEqual(1176);
    expect(active30.kills.p50).toBeLessThanOrEqual(1300);
    expect(active30.reincarnations.p50).toBe(15);
    // H1/H2 — a full roster no longer eats captures in silence, and H3 — the
    // first card is always an unseen form while the binder is incomplete.
    expect(active30.fullRosters).toBe(100);
    expect(active30.released.p10).toBeGreaterThanOrEqual(8);
    expect(active30.released.p50).toBeGreaterThanOrEqual(18);
    expect(active30.unseenFirstCardRatio).toBe(1);
  }, 30_000);
});

// v0.4 "expedition payoff" — the three changes the v4 fun review approved:
// A3' a full roster releases a boss instead of voiding the draw in silence,
// A5' the hero offer's first slot opens up once the top rank is fully owned,
// A1' a display-only rest gauge that must never overlap the existing HUD.
// Pure core + the DOM-free HUD, so everything runs under vitest's node env.

import { describe, expect, it } from 'vitest';
import {
  createEngine,
  DEFAULT_SAVE,
  HERO_FORMS,
  HERO_REST_MS,
  monsterForIndex,
  mulberry32,
  RELEASES_PER_SOUL,
  rollHeroChoices,
  ROSTER_CAP,
} from '../src/core/index.js';
import type { Companion, GameEvent, GameState, HeroProgress, SaveFile } from '../src/core/index.js';
import { newHeroProgress } from '../src/core/hero.js';
import {
  COUNTER_TOP,
  drawExpedition,
  EXPEDITION_H,
  EXPEDITION_SOULS_X,
  EXPEDITION_W,
  HUD_MARGIN,
} from '../src/renderer/hud.js';
import type { SpriteCanvas } from '../src/renderer/sprites/index.js';

/** A save whose roster is already at the cap, so every capture is a release. */
function fullRosterSave(): SaveFile {
  const companions: Companion[] = Array.from({ length: ROSTER_CAP }, (_, i) => ({
    id: `c${i + 1}`,
    speciesId: 'slime',
    // Ascending power, so the weakest keeper is always c1.
    bossIndex: i,
    level: 1,
    stars: 0,
  }));
  return { ...DEFAULT_SAVE, companions, nextCompanionId: ROSTER_CAP + 1, items: {}, pvpParty: [] };
}

/** Drive one engine for `attacks` inputs and return every event it emitted. */
function play(save: SaveFile | null, seed: number, attacks: number): { state: GameState; events: GameEvent[] } {
  const engine = createEngine(save, mulberry32(seed));
  const events: GameEvent[] = [];
  for (let i = 0; i < attacks; i++) events.push(...engine.attack('keyboard'));
  return { state: engine.getState(), events };
}

describe('A3 — a full roster releases the boss instead of voiding it (H1/H2)', () => {
  it('never swallows a capture draw: every full-roster boss draw emits an event', () => {
    // Invariant, not a distribution: over 100 seeds the count of releases must
    // equal the count of successful draws that the cap turned away, and the
    // engine must never capture past the cap.
    for (let seed = 1; seed <= 100; seed++) {
      const { state, events } = play(fullRosterSave(), seed, 4000);
      const released = events.filter((e) => e.type === 'companionReleased');
      const captured = events.filter((e) => e.type === 'bossCaptured');
      expect(captured).toHaveLength(0);
      expect(state.companions).toHaveLength(ROSTER_CAP);
      expect(state.releasedCount).toBe(released.length);
      // Souls follow the fixed conversion, with no partial credit lost.
      const paid = released.reduce((sum, e) => sum + (e.type === 'companionReleased' ? e.souls : 0), 0);
      expect(paid).toBe(Math.floor(released.length / RELEASES_PER_SOUL));
      expect(state.souls).toBe(paid);
    }
  });

  it('pays exactly one soul on every RELEASES_PER_SOUL-th release and persists the tally', () => {
    const { state, events } = play(fullRosterSave(), 7, 4000);
    const released = events.filter((e) => e.type === 'companionReleased');
    expect(released.length).toBeGreaterThan(0);
    let seen = 0;
    for (const e of released) {
      if (e.type !== 'companionReleased') continue;
      seen++;
      expect(e.souls).toBe(seen % RELEASES_PER_SOUL === 0 ? 1 : 0);
      expect(e.bossIndex).toBeGreaterThanOrEqual(0);
    }
    // The tally survives a save/resume so the conversion keeps its parity.
    const resumed = createEngine({ ...fullRosterSave(), releasedCount: state.releasedCount }, mulberry32(1));
    expect(resumed.getState().releasedCount).toBe(state.releasedCount);
    expect(resumed.toSave().releasedCount).toBe(state.releasedCount);
  });

  it('flags whether the released boss beat the roster\'s weakest keeper', () => {
    // A roster of deep bosses is worth more than any early release …
    const strong: SaveFile = {
      ...fullRosterSave(),
      companions: Array.from({ length: ROSTER_CAP }, (_, i) => ({
        id: `c${i + 1}`, speciesId: 'dragon', bossIndex: 400, level: 1, stars: 0,
      })),
    };
    const strongRuns = play(strong, 3, 2000).events
      .filter((e): e is Extract<GameEvent, { type: 'companionReleased' }> => e.type === 'companionReleased');
    expect(strongRuns.length).toBeGreaterThan(0);
    expect(strongRuns.every((e) => !e.strongerThanWeakest)).toBe(true);

    // … while a roster of index-0 slimes is beaten by anything deeper.
    const weak: SaveFile = {
      ...fullRosterSave(),
      companions: Array.from({ length: ROSTER_CAP }, (_, i) => ({
        id: `c${i + 1}`, speciesId: 'slime', bossIndex: 0, level: 1, stars: 0,
      })),
    };
    const weakRuns = play(weak, 3, 2000).events
      .filter((e): e is Extract<GameEvent, { type: 'companionReleased' }> => e.type === 'companionReleased');
    expect(weakRuns.length).toBeGreaterThan(0);
    expect(weakRuns.some((e) => e.strongerThanWeakest)).toBe(true);
  });

  it('leaves the RNG stream untouched: an open roster plays exactly as before', () => {
    // The capture draw is still consumed once per boss kill, so a run that
    // never fills its roster must be bit-identical to the pre-change pacing.
    for (const seed of [1, 17, 55, 90]) {
      const open = play(null, seed, 3000);
      expect(open.events.filter((e) => e.type === 'companionReleased')).toHaveLength(0);
      expect(open.state.releasedCount).toBe(0);
      expect(open.state.companions.length).toBeLessThanOrEqual(ROSTER_CAP);
    }
  });
});

describe('A5 — the offer keeps finding unseen forms past the top rank (H3)', () => {
  const heroAt = (reincarnations: number, collection: HeroProgress['collection']): HeroProgress =>
    ({ ...newHeroProgress(), reincarnations, collection });

  it('offers an unseen form in slot 0 once the top rank is fully collected', () => {
    // Everything at rank 5 owned, nothing below it — the old rule was stuck
    // re-offering the same ten forms forever.
    const topRank = HERO_FORMS.filter((f) => f.rank === 5);
    const hero = heroAt(20, topRank.map((f) => ({ formId: f.id, buffPercent: 20 })));
    let unseenFirst = 0;
    for (let seed = 1; seed <= 100; seed++) {
      const choices = rollHeroChoices(hero, mulberry32(seed));
      expect(choices).toHaveLength(3);
      if (!hero.collection.some((r) => r.formId === choices[0]!.formId)) unseenFirst++;
    }
    expect(unseenFirst).toBe(100);
  });

  it('still guarantees the newest rank while that rank has anything unseen', () => {
    for (let reincarnations = 0; reincarnations < 5; reincarnations++) {
      const rank = Math.min(5, reincarnations + 1);
      for (let seed = 1; seed <= 20; seed++) {
        const first = rollHeroChoices(heroAt(reincarnations, []), mulberry32(seed))[0]!;
        expect(HERO_FORMS.find((f) => f.id === first.formId)?.rank).toBe(rank);
      }
    }
  });

  it('always offers three distinct elements and keeps the roll range', () => {
    const owned = HERO_FORMS.slice(0, 40).map((f) => ({ formId: f.id, buffPercent: 25 }));
    for (const collection of [[], owned, HERO_FORMS.map((f) => ({ formId: f.id, buffPercent: 25 }))]) {
      for (let seed = 1; seed <= 50; seed++) {
        const choices = rollHeroChoices(heroAt(20, collection), mulberry32(seed));
        const types = choices.map((r) => HERO_FORMS.find((f) => f.id === r.formId)!.type);
        expect(new Set(types).size).toBe(3);
        for (const roll of choices) {
          expect(roll.buffPercent).toBeGreaterThanOrEqual(10);
          expect(roll.buffPercent).toBeLessThanOrEqual(25);
        }
      }
    }
  });

  it('consumes the same number of RNG draws as the previous rule', () => {
    // Two draws per slot, six per offer — the shared stream is what the
    // pacing baseline was measured on, so its length may not move.
    for (const collection of [[], HERO_FORMS.map((f) => ({ formId: f.id, buffPercent: 25 }))]) {
      let draws = 0;
      const base = mulberry32(42);
      const counting = { next: (): number => { draws++; return base.next(); } };
      rollHeroChoices(heroAt(20, collection), counting);
      expect(draws).toBe(6);
    }
  });

  it('drives the binder past the old 14-form ceiling under an always-accept policy', () => {
    // Simulated policy, not a human: accept the first card every time.
    const collected = new Set<string>();
    let hero = newHeroProgress();
    const rng = mulberry32(9);
    for (let i = 0; i < 50; i++) {
      const choices = rollHeroChoices(hero, rng);
      const pick = choices[0]!;
      collected.add(pick.formId);
      hero = {
        ...hero,
        reincarnations: hero.reincarnations + 1,
        collection: hero.collection.some((r) => r.formId === pick.formId)
          ? hero.collection
          : [...hero.collection, pick],
      };
    }
    // The old slot-0 rule capped this at 14 (4 low ranks + 10 at rank 5).
    expect(collected.size).toBe(50);
  });
});

describe('A1 — the expedition gauge is display-only and stays out of the way (H2b/H7)', () => {
  interface Rect { x: number; y: number; w: number; h: number }

  const paint = (hero?: HeroProgress, monsterIndex = 40): Rect[] => {
    const rects: Rect[] = [];
    const ctx: SpriteCanvas = {
      fillStyle: '',
      fillRect(x: number, y: number, w: number, h: number): void { rects.push({ x, y, w, h }); },
    };
    const monster = monsterForIndex(monsterIndex);
    const state = {
      ...createEngine(null, mulberry32(1)).getState(),
      monster, monsterHp: monster.maxHp,
      ...(hero ? { hero } : {}),
    } as GameState;
    drawExpedition(ctx, state);
    return rects;
  };

  const resting = (restRemainingMs: number): HeroProgress => ({ ...newHeroProgress(), restRemainingMs });

  it('paints nothing at all when no rest is running', () => {
    expect(paint(undefined)).toEqual([]);
    expect(paint(resting(0))).toEqual([]);
    expect(paint(newHeroProgress())).toEqual([]);
  });

  it('drains monotonically over the rest and disappears at zero (H2b)', () => {
    const fillWidth = (ms: number): number => {
      const rects = paint(resting(ms));
      // drawMeter paints frame, interior, then the fill — the fill is last.
      return rects.length >= 3 ? rects[rects.length - 1]!.w : 0;
    };
    let prev = Number.POSITIVE_INFINITY;
    for (let ms = HERO_REST_MS; ms > 0; ms -= HERO_REST_MS / 20) {
      const w = fillWidth(ms);
      expect(w).toBeLessThanOrEqual(prev);
      prev = w;
    }
    expect(paint(resting(0))).toEqual([]);
  });

  it('never leaves its declared pixel budget, whatever the depth (H7)', () => {
    // The whole readout lives in x[2,60) y[16,21) — clear of the hero
    // (x[66,94)), the monster and counters (x>=150) and the banner (y=20 is
    // only reached by text baselines at x>=64).
    const boxRight = EXPEDITION_SOULS_X + 4 * 4; // <=4 glyphs at FONT_ADVANCE 4
    expect(HUD_MARGIN).toBe(2);
    expect(COUNTER_TOP).toBe(16);
    expect(boxRight).toBeLessThanOrEqual(60);
    for (const index of [0, 8, 100, 5000, 10_000_000]) {
      for (const rect of paint(resting(HERO_REST_MS / 2), index)) {
        expect(rect.x).toBeGreaterThanOrEqual(HUD_MARGIN);
        expect(rect.x + rect.w).toBeLessThanOrEqual(60);
        expect(rect.y).toBeGreaterThanOrEqual(COUNTER_TOP);
        expect(rect.y + rect.h).toBeLessThanOrEqual(COUNTER_TOP + 5);
      }
    }
    expect(EXPEDITION_W).toBe(40);
    expect(EXPEDITION_H).toBe(3);
  });

  it('changes no game state — it only reads (H2b: display is not a reward)', () => {
    const engine = createEngine(null, mulberry32(5));
    const before = engine.toSave();
    paint(resting(HERO_REST_MS));
    expect(engine.toSave()).toEqual(before);
  });
});

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/**
 * 3 different elements; unowned forms preferred. Slot 0 shows the top unlocked
 * rank while anything there is still unowned; once that rank is fully collected
 * it falls back to any unseen form, so the binder keeps growing past 14 instead
 * of re-offering the same top ten forever. The RNG draw count per slot is
 * unchanged, so the shared stream — and the pacing measured on it — is intact.
 */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const owned = (f: HeroForm): boolean => hero.collection.some((r) => r.formId === f.id);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    const eligible = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type));
    const top = eligible.filter((f) => f.rank === rank);
    const keepTop = top.some((f) => !owned(f)) || !eligible.some((f) => !owned(f));
    let pool = i === 0 && keepTop ? top : eligible;
    const unseen = pool.filter((f) => !owned(f));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Companion collection — SPEC F32 (Assumptions 5/23/24/26; GAME_DESIGN_V2
// §4/§6). Pure TypeScript, zero imports of electron/DOM/node. Every export is
// total and never mutates its input: applyCollection returns fresh objects or
// an { error }, so the caller can apply it straight onto live engine state.

import { simulateBattle } from './battle.js';
import { monsterForIndex, sizeOf, typeOf } from './monsters.js';
import { monsterMaxHp } from './formulas.js';
import { effectivePower } from './types-chart.js';
import type { MonsterType } from './types-chart.js';
import type { BattleHeroes, Blow } from './battle.js';
import { heroBuffedPower } from './hero.js';
import type { HeroAction, HeroRoll } from './hero.js';
import type { Companion } from './save.js';
import type { Rng } from './rng.js';
import type { GameState, PvpResultAction } from './types.js';

/** A companion never levels past this (consume/reincarnate both cap here). */
export const COMPANION_MAX_LEVEL = 10;

/** How many companions fight together — field volley and PvP party (F61). */
export const PARTY_SIZE = 5;

/** Roster cap (save.ts keeps its own copy for parsing). */
export const ROSTER_CAP = 30;

/** Rebirth unlocks at this monster index (Assumption 5). */
export const REBIRTH_MIN_INDEX = 40;

/** Companion attack power (Assumption 24) — bigint, unbounded. */
export const companionPower = (c: Companion): bigint => {
  const base = monsterMaxHp(c.bossIndex) / 20n;
  return (base < 1n ? 1n : base) * BigInt(c.level) * 2n ** BigInt(c.stars);
};

/** Numeric part of a 'cN' id — the tie-breaker (same rule as parseSave). */
const idNum = (id: string): number => Number(id.replace(/\D/g, '') || 0);

/** Descending bigint comparator. */
const desc = (a: bigint, b: bigint): number => (a === b ? 0 : b > a ? 1 : -1);

/**
 * The PARTY_SIZE best companions against `enemyType` (F61): effective power
 * desc, ties → higher raw power → lower numeric id. Without a type the raw
 * power decides, which is what the PvP default `autoParty` wants.
 */
export function activeCompanions(
  cs: readonly Companion[],
  enemyType?: MonsterType,
  hero?: HeroRoll,
): Companion[] {
  const power = (c: Companion): bigint => heroBuffedPower(companionPower(c), typeOf(c.speciesId), hero);
  const effective = (c: Companion): bigint =>
    enemyType === undefined
      ? power(c)
      : effectivePower(power(c), typeOf(c.speciesId), enemyType);
  return [...cs]
    .sort(
      (a, b) =>
        desc(effective(a), effective(b)) ||
        desc(companionPower(a), companionPower(b)) ||
        idNum(a.id) - idNum(b.id),
    )
    .slice(0, PARTY_SIZE);
}

/** The PvP default party: the PARTY_SIZE strongest by raw power. */
export function autoParty(cs: readonly Companion[], hero?: HeroRoll): Companion[] {
  return activeCompanions(cs, undefined, hero);
}

/** `ids` resolved against `cs` in the given order; unknown/duplicate dropped. */
function resolveIds(cs: readonly Companion[], ids: readonly string[]): Companion[] {
  const party: Companion[] = [];
  for (const id of ids) {
    if (party.length >= PARTY_SIZE) break;
    const c = cs.find((x) => x.id === id);
    if (c && !party.includes(c)) party.push(c);
  }
  return party;
}

/** The manual PvP party; an empty result falls back to `autoParty` (F61). */
export function pvpParty(cs: readonly Companion[], ids: readonly string[], hero?: HeroRoll): Companion[] {
  const party = resolveIds(cs, ids);
  return party.length > 0 ? party : autoParty(cs, hero);
}

/** Draw order of a party: biggest first (back row), ties keep party order. */
export function partyOrder(party: readonly Companion[]): Companion[] {
  return [...party].sort((a, b) => sizeOf(b.speciesId) - sizeOf(a.speciesId));
}

/**
 * Events produced here (GAME_DESIGN_V2 §6). T28 folds both variants into the
 * `GameEvent` union in types.ts; every other action returns no events.
 * ponytail: declared locally until then — types.ts is owned by T26/T28/T29.
 */
export type CollectionEvent =
  | { type: 'rebirth'; souls: number }
  | { type: 'pvpResolved'; won: boolean; stolen: Companion | null; lostId: string | null };

/** Every roster/prestige operation the menu and the net layer can request. */
export type CollectionAction =
  | HeroAction
  | { type: 'consume'; targetId: string; foodId: string }
  | { type: 'fuse'; aId: string; bId: string }
  | { type: 'reincarnate'; id: string }
  | { type: 'sacrifice'; id: string }
  | { type: 'rebirth' }
  | { type: 'addCompanion'; companion: Companion }
  | { type: 'removeCompanions'; ids: string[] }
  | { type: 'setPvpParty'; ids: string[] }
  | PvpResultAction;

export type CollectionResult =
  | { state: GameState; events: CollectionEvent[] }
  | { error: string };

/** Fresh roster: `dropIds` removed, `editId` replaced by `edit(c)`, rest copied. */
function reroster(
  cs: readonly Companion[],
  dropIds: readonly string[],
  editId?: string,
  edit?: (c: Companion) => Companion,
): Companion[] {
  return cs
    .filter((c) => !dropIds.includes(c.id))
    .map((c) => (edit && c.id === editId ? edit(c) : { ...c }));
}

/** Fresh state: nothing of `state` is shared with the result. */
function next(
  state: Readonly<GameState>,
  companions: Companion[],
  patch: Partial<GameState> = {},
  events: CollectionEvent[] = [],
): CollectionResult {
  return {
    state: {
      ...state,
      items: { ...state.items },
      monster: { ...state.monster },
      companions,
      ...patch,
    },
    events,
  };
}

/** Push `c` re-minted as `c${nextCompanionId}`; null when the roster is full. */
function minted(
  companions: Companion[],
  nextCompanionId: number,
  c: Companion,
): Companion | null {
  if (companions.length >= ROSTER_CAP) return null;
  const fresh: Companion = { ...c, id: `c${nextCompanionId}` };
  companions.push(fresh);
  return fresh;
}

/**
 * Apply one lifecycle action (Assumption 26). Total: an unknown action type,
 * an unknown/duplicate companion id or an unmet precondition yields
 * `{ error }` and the caller keeps its state; success yields a brand-new
 * state plus the events of GAME_DESIGN_V2 §6.
 */
export function applyCollection(
  state: Readonly<GameState>,
  action: CollectionAction,
): CollectionResult {
  const cs = state.companions;
  const find = (id: string): Companion | undefined => cs.find((c) => c.id === id);

  switch (action.type) {
    case 'consume': {
      const target = find(action.targetId);
      const food = find(action.foodId);
      if (!target || !food || target.id === food.id) return { error: 'consume: bad ids' };
      return next(
        state,
        reroster(cs, [food.id], target.id, (c) => ({
          ...c,
          level: Math.min(COMPANION_MAX_LEVEL, c.level + 1 + food.stars),
        })),
      );
    }
    case 'fuse': {
      const a = find(action.aId);
      const b = find(action.bId);
      if (!a || !b || a.id === b.id) return { error: 'fuse: bad ids' };
      if (a.speciesId !== b.speciesId || a.stars !== b.stars) {
        return { error: 'fuse: needs the same species and stars' };
      }
      return next(
        state,
        reroster(cs, [b.id], a.id, (c) => ({
          ...c,
          bossIndex: Math.max(a.bossIndex, b.bossIndex),
          level: 1,
          stars: c.stars + 1,
        })),
      );
    }
    case 'reincarnate': {
      const c = find(action.id);
      if (!c) return { error: 'reincarnate: unknown id' };
      if (c.level !== COMPANION_MAX_LEVEL) return { error: 'reincarnate: needs max level' };
      return next(
        state,
        reroster(cs, [], c.id, (x) => ({ ...x, level: 1, stars: x.stars + 1 })),
      );
    }
    case 'sacrifice': {
      const c = find(action.id);
      if (!c) return { error: 'sacrifice: unknown id' };
      return next(state, reroster(cs, [c.id]), { souls: state.souls + 1 + c.stars });
    }
    case 'rebirth': {
      if (state.monster.index < REBIRTH_MIN_INDEX) {
        return { error: `rebirth: needs monster index ${REBIRTH_MIN_INDEX}` };
      }
      const souls = state.souls + Math.floor(state.monster.index / 8);
      const first = monsterForIndex(0);
      return next(
        state,
        reroster(cs, []),
        {
          level: 1,
          xp: 0,
          monster: first,
          monsterHp: first.maxHp,
          souls,
          rebirths: state.rebirths + 1,
        },
        [{ type: 'rebirth', souls }],
      );
    }
    case 'addCompanion': {
      const companions = reroster(cs, []);
      if (!minted(companions, state.nextCompanionId, action.companion)) {
        return { error: 'addCompanion: roster is full' };
      }
      return next(state, companions, { nextCompanionId: state.nextCompanionId + 1 });
    }
    case 'removeCompanions':
      return next(state, reroster(cs, action.ids));
    case 'setPvpParty':
      // Never an error and no event: an all-unknown list just empties it.
      return next(state, reroster(cs, []), {
        pvpParty: resolveIds(cs, action.ids).map((c) => c.id),
      });
    case 'pvpResult': {
      const companions = reroster(cs, action.lostId === null ? [] : [action.lostId]);
      // A steal into a full roster is void, never an error (Assumption 23).
      const stolen = action.stolen && minted(companions, state.nextCompanionId, action.stolen);
      return next(
        state,
        companions,
        { nextCompanionId: state.nextCompanionId + (stolen ? 1 : 0) },
        [
          {
            type: 'pvpResolved',
            won: action.won,
            stolen: stolen ?? null,
            lostId: action.lostId,
          },
        ],
      );
    }
    default:
      return { error: 'unknown action' };
  }
}

/** Chance an attacking win also carries a companion home (GAME_DESIGN_V3 §5). */
export const STEAL_CHANCE = 0.15;

/**
 * Resolve one asynchronous PvP exchange (SPEC F37; GAME_DESIGN_V3 §5). The
 * verdict and the blow list come from the seedless `simulateBattle`; the rng
 * only decides the loot. Shared byte-for-byte with the server, which calls it
 * with `mulberry32(seed)` and moves `moved` between the stored rosters — so
 * exactly 2 draws happen per call, the victim draw included even when nobody
 * can be stolen, and the client can replay the same match from the seed.
 * Only the attacker ever steals: a losing attacker keeps its whole roster.
 * ponytail: `attackerRosterSize` defaults to the party size so the v2 3-arg
 * call still compiles; T60 passes the real roster length.
 */
export function resolvePvp(
  attacker: readonly Companion[],
  defender: readonly Companion[],
  rng: Rng,
  attackerRosterSize = attacker.length,
  heroes: BattleHeroes = {},
): { attackerWon: boolean; moved: Companion | null; blows: Blow[] } {
  const { attackerWon, blows } = simulateBattle(attacker, defender, heroes);
  const stealRoll = rng.next() < STEAL_CHANCE;
  const victim = defender[Math.floor(rng.next() * defender.length)] ?? null;
  return {
    attackerWon,
    moved: attackerWon && stealRoll && attackerRosterSize < ROSTER_CAP ? victim : null,
    blows,
  };
}

// Loot tables — SPEC F09 / Assumptions 3, 6, 15.
// Every kill drops coins 1 + floor(index/3); 25% chance of exactly one
// weighted trinket. Randomness comes ONLY from the injected Rng.

import type { Rng } from './rng.js';
import type { ItemDef, ItemDrop } from './types.js';

/** The always-dropped currency item. */
export const COIN_ITEM: ItemDef = { id: 'coin', name: 'Coin', kind: 'coin' };

/** Chance that a kill also drops one trinket (SPEC Assumption 3). */
export const TRINKET_CHANCE = 0.25;

export interface WeightedTrinket {
  readonly item: ItemDef;
  readonly weight: number;
}

/** Weighted trinket table (SPEC F09). Never reorder — weights are frozen. */
export const TRINKET_TABLE: readonly WeightedTrinket[] = [
  { item: { id: 'sword_shard', name: 'Sword Shard', kind: 'trinket' }, weight: 5 },
  { item: { id: 'slime_gel', name: 'Slime Gel', kind: 'trinket' }, weight: 4 },
  { item: { id: 'bone', name: 'Bone', kind: 'trinket' }, weight: 3 },
  { item: { id: 'gem', name: 'Gem', kind: 'trinket' }, weight: 2 },
  { item: { id: 'crown', name: 'Crown', kind: 'trinket' }, weight: 1 },
];

const TOTAL_WEIGHT = TRINKET_TABLE.reduce((sum, t) => sum + t.weight, 0);

/** Coins dropped by the monster at `index`: 1 + floor(index/3), clamped total. */
export function coinsForIndex(index: number): number {
  return 1 + Math.floor(Math.max(0, Math.floor(index)) / 3);
}

function pickWeightedTrinket(rng: Rng): ItemDef {
  let r = rng.next() * TOTAL_WEIGHT;
  for (const entry of TRINKET_TABLE) {
    r -= entry.weight;
    if (r < 0) {
      return entry.item;
    }
  }
  // Unreachable while rng.next() < 1; keeps the function total anyway.
  return COIN_ITEM;
}

/**
 * Roll the drops for killing the monster at 0-based global `monsterIndex`:
 * always exactly one coin drop of amount 1 + floor(index/3) (first element),
 * plus a TRINKET_CHANCE chance of exactly one weighted trinket (amount 1).
 * Consumes 1 rng draw normally, 2 when a trinket drops.
 */
export function rollLoot(rng: Rng, monsterIndex: number): ItemDrop[] {
  const drops: ItemDrop[] = [{ item: COIN_ITEM, amount: coinsForIndex(monsterIndex) }];
  if (rng.next() < TRINKET_CHANCE) {
    drops.push({ item: pickWeightedTrinket(rng), amount: 1 });
  }
  return drops;
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;
/**
 * Releases needed for one soul. 2 keeps the 30 min payout at ~+11 souls, whose
 * measured upper bound on kills (+4.3%) stays inside the ±5% pacing budget.
 */
export const RELEASES_PER_SOUL = 2;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      releasedCount: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    releasedCount: save.releasedCount ?? 0,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    const drew = killed.boss && rng.next() < CAPTURE_CHANCE;
    if (drew && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    } else if (drew) {
      // A full roster used to void the draw in silence. Release it instead:
      // every second release pays one soul, and the event says whether the
      // roster's weakest keeper was worth less than what just walked away.
      state.releasedCount += 1;
      const souls = state.releasedCount % RELEASES_PER_SOUL === 0 ? 1 : 0;
      state.souls += souls;
      const released = companionPower({ id: '', speciesId: killed.speciesId, bossIndex: killed.index, level: 1, stars: 0 });
      const weakest = state.companions.reduce(
        (min, c) => (companionPower(c) < min ? companionPower(c) : min), released);
      events.push({ type: 'companionReleased', speciesId: killed.speciesId, bossIndex: killed.index,
        souls, strongerThanWeakest: weakest < released });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        releasedCount: state.releasedCount,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

// Real engine, injected RNG/clock, no wall time or input hooks. A simulation
// measures pacing; it cannot certify that a human finds the game enjoyable.
import { writeFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { createEngine, heroReady, mulberry32 } from '../src/core/index.js';

type Profile = 'active' | 'idle' | 'intermittent';
interface Sample { minutes: number; profile: Profile; seed: number; kills: number; firstOfferSec: number | null;
  reincarnations: number; collected: number; coins: number; companions: number; longestKillGapSec: number;
  /** v0.4 expedition payoff: full-roster releases, and how many were the first card unseen. */
  released: number; souls: number; unseenFirstCards: number; offers: number }

function simulate(profile: Profile, seed: number): Sample[] {
  const engine = createEngine(null, mulberry32(seed));
  const result: Sample[] = [];
  let firstOfferSec: number | null = null;
  let lastKill = 0;
  let longestKillGapSec = 0;
  let released = 0;
  let unseenFirstCards = 0;
  let offers = 0;
  for (let sec = 1; sec <= 1800; sec++) {
    // All profiles get a two-minute onboarding. Idle then stops input;
    // intermittent works 15 seconds per minute; active inputs twice a second.
    const inputs = sec <= 120 || profile === 'active' || (profile === 'intermittent' && sec % 60 < 15) ? 2 : 0;
    let killed = false;
    for (let i = 0; i < inputs; i++) {
      const hit = engine.attack('keyboard');
      killed = hit.some((e) => e.type === 'monsterKilled') || killed;
      released += hit.filter((e) => e.type === 'companionReleased').length;
    }
    // Do not short-circuit engine steps when an earlier input killed.
    const events = engine.tick(1000);
    killed = events.some((e) => e.type === 'monsterKilled') || killed;
    released += events.filter((e) => e.type === 'companionReleased').length;
    if (killed) {
      longestKillGapSec = Math.max(longestKillGapSec, sec - lastKill);
      lastKill = sec;
    }
    const state = engine.getState();
    if (heroReady(state.level, state.hero)) {
      firstOfferSec ??= sec;
      engine.apply({ type: 'heroOffer' });
      const hero = engine.getState().hero!;
      // Choose the first card, without any gold rerolls — the same policy the
      // v0.4 baseline used, so before/after numbers stay comparable.
      offers++;
      if (!hero.collection.some((r) => r.formId === hero.choices[0]!.formId)) unseenFirstCards++;
      engine.apply({ type: 'heroChoose', formId: hero.choices[0]!.formId, offerSerial: hero.offerSerial });
    }
    if ([300, 900, 1800].includes(sec)) {
      const current = engine.getState();
      result.push({ minutes: sec / 60, profile, seed, kills: current.killCount,
        firstOfferSec, reincarnations: current.hero?.reincarnations ?? 0,
        collected: current.hero?.collection.length ?? 0, coins: current.coins,
        companions: current.companions.length,
        longestKillGapSec: Math.max(longestKillGapSec, sec - lastKill),
        released, souls: current.souls, unseenFirstCards, offers });
    }
  }
  return result;
}

describe('v0.4 deterministic pacing playtest', () => {
  it('checks 100 seeds across active, warm-idle and intermittent play at 5/15/30 minutes', () => {
    const samples = (['active', 'idle', 'intermittent'] as const).flatMap((profile) =>
      Array.from({ length: 100 }, (_, i) => {
        const sample = simulate(profile, i + 1);
        if (process.env.DESMON_BALANCE_REPORT && (i + 1) % 25 === 0) process.stdout.write(`${profile}: ${i + 1}/100 seeds\n`);
        return sample;
      }).flat());
    const quantiles = (values: number[]) => {
      const sorted = [...values].sort((a, b) => a - b);
      return { p10: sorted[Math.floor((sorted.length - 1) * .1)]!, p50: sorted[Math.floor((sorted.length - 1) * .5)]!, p90: sorted[Math.floor((sorted.length - 1) * .9)]! };
    };
    const scenarios = (['active', 'idle', 'intermittent'] as const).flatMap((profile) => [5, 15, 30].map((minutes) => {
      const rows = samples.filter((s) => s.profile === profile && s.minutes === minutes);
      return { profile, minutes, samples: rows.length,
        firstOfferReached: rows.filter((r) => r.firstOfferSec !== null).length,
        firstOfferSec: quantiles(rows.flatMap((r) => r.firstOfferSec === null ? [] : [r.firstOfferSec])),
        kills: quantiles(rows.map((r) => r.kills)), reincarnations: quantiles(rows.map((r) => r.reincarnations)),
        collected: quantiles(rows.map((r) => r.collected)), coins: quantiles(rows.map((r) => r.coins)),
        longestKillGapSec: quantiles(rows.map((r) => r.longestKillGapSec)),
        released: quantiles(rows.map((r) => r.released)), souls: quantiles(rows.map((r) => r.souls)),
        unseenFirstCardRatio: rows.reduce((sum, r) => sum + (r.offers === 0 ? 1 : r.unseenFirstCards / r.offers), 0) / rows.length,
        fullRosters: rows.filter((r) => r.companions === 30).length };
    }));
    const report = { version: '0.4.0', kind: 'simulated-not-human', seeds: '1..100',
      inputModel: '2 inputs/s; 120s onboarding, then idle=0/s; intermittent=15s/min; choose first offer, no rerolls, no companion management',
      scenarios, rawSamples: samples };
    if (process.env.DESMON_BALANCE_REPORT) writeFileSync(process.env.DESMON_BALANCE_REPORT, JSON.stringify(report, null, 2) + '\n');
    expect(samples).toHaveLength(900);
    expect(samples.every((s) => s.coins >= 0 && s.collected <= 50 && s.companions <= 30)).toBe(true);
    const active = scenarios.find((s) => s.profile === 'active' && s.minutes === 5)!;
    expect(active.firstOfferReached).toBe(100);
    expect(active.firstOfferSec.p90).toBeLessThanOrEqual(300);
    for (const profile of ['active', 'idle', 'intermittent']) {
      const early = scenarios.find((s) => s.profile === profile && s.minutes === 5)!;
      const late = scenarios.find((s) => s.profile === profile && s.minutes === 30)!;
      expect(late.kills.p50).toBeGreaterThan(early.kills.p50);
      expect(late.reincarnations.p50).toBeGreaterThan(early.reincarnations.p50);
    }
    // H4 — the v0.4 expedition payoff may not move the measured pacing more
    // than the ±5% budget the design was approved under (baseline: first offer
    // 79s, active 30 min 1,238 kills / 15 reincarnations).
    const active30 = scenarios.find((s) => s.profile === 'active' && s.minutes === 30)!;
    expect(active.firstOfferSec.p50).toBeGreaterThanOrEqual(74);
    expect(active.firstOfferSec.p50).toBeLessThanOrEqual(84);
    expect(active30.kills.p50).toBeGreaterThanOrEqual(1176);
    expect(active30.kills.p50).toBeLessThanOrEqual(1300);
    expect(active30.reincarnations.p50).toBe(15);
    // H1/H2 — a full roster no longer eats captures in silence, and H3 — the
    // first card is always an unseen form while the binder is incomplete.
    expect(active30.fullRosters).toBe(100);
    expect(active30.released.p10).toBeGreaterThanOrEqual(8);
    expect(active30.released.p50).toBeGreaterThanOrEqual(18);
    expect(active30.unseenFirstCardRatio).toBe(1);
  }, 30_000);
});

import { writeFileSync } from 'node:fs';
import { describe, it } from 'vitest';
import { createEngine, heroReady, mulberry32 } from '../src/core/index.js';
import { heroForm } from '../src/core/hero.js';

const BASE = (r: number) => 50 + 25 * Math.min(100, r);
const PRICE = (r: number, k: number) => BASE(r) * Math.pow(2, Math.min(k, 5));

type Policy = 'baseline' | 'bestEquip';

interface Row { seed: number; policy: Policy; kills: number; coins: number; collected: number;
  reinc: number; equippedBuff: number; bestBuff: number;
  // offline economy of the proposed 각인 재추첨 (side RNG, gold accounted offline)
  spend: number; rerolls: number; blocked: number; chasedBest: number; chasedEquipped: number;
  freeBestParty: number; chaseBestParty: number; satOffer: number; spendUntilSat: number; restIfRational: number }

function run(seed: number, policy: Policy): Row {
  const engine = createEngine(null, mulberry32(seed));
  const side = mulberry32(seed * 7919 + 13); // independent stream for the simulated buff redraw
  let spend = 0, rerolls = 0, blocked = 0;
  const chased: Record<string, number> = {}; // formId -> best engraving under the chase policy
  let chasedEquipped = 0;
  let spendUntilSat = 0; let satOffer = 0; let offerNo = 0;
  const freeParty: number[] = []; const chaseParty: number[] = [];
  for (let sec = 1; sec <= 1800; sec++) {
    for (let i = 0; i < 2; i++) engine.attack('keyboard');
    engine.tick(1000);
    const st = engine.getState();
    if (heroReady(st.level, st.hero)) {
      engine.apply({ type: 'heroOffer' });
      const hero = engine.getState().hero!;
      const r = hero.reincarnations;
      // ---- offline: 각인 재추첨 "25를 노린다" policy on this offer ----
      offerNo++;
      let coins = engine.getState().coins - spend;
      const cards = hero.choices.map((c) => c.buffPercent);
      let k = 0;
      for (;;) {
        if (cards[0]! >= 25) break;
        const p = PRICE(r, k);
        if (coins < p) { blocked++; break; }
        coins -= p; spend += p; rerolls++; k++;
        for (let i = 0; i < 3; i++) cards[i] = Math.max(cards[i]!, 10 + Math.min(15, Math.floor(side.next() * 16)));
      }
      const pick = hero.choices[0]!;
      chased[pick.formId] = Math.max(chased[pick.formId] ?? 0, cards[0]!);
      chasedEquipped = chased[pick.formId]!;
      if (heroForm(pick.formId)!.buff === 'party') { chaseParty.push(cards[0]!); freeParty.push(pick.buffPercent); }
      // saturation: once ANY party form in the chase collection is 25, further gold buys no power
      if (satOffer === 0 && Math.max(0, ...chaseParty) >= 25) { satOffer = offerNo; spendUntilSat = spend; }
      // ---- real engine choice (unchanged, first card) ----
      engine.apply({ type: 'heroChoose', formId: pick.formId, offerSerial: hero.offerSerial });
      if (policy === 'bestEquip') {
        const h = engine.getState().hero!;
        const best = [...h.collection].sort((a, b) =>
          (heroForm(b.formId)!.buff === 'party' ? b.buffPercent : 0) - (heroForm(a.formId)!.buff === 'party' ? a.buffPercent : 0))[0];
        if (best && best.formId !== h.equipped.formId) engine.apply({ type: 'heroEquip', formId: best.formId });
      }
    }
  }
  const st = engine.getState();
  const h = st.hero!;
  return { seed, policy, kills: st.killCount, coins: st.coins, collected: h.collection.length,
    reinc: h.reincarnations, equippedBuff: h.equipped.buffPercent,
    bestBuff: Math.max(0, ...h.collection.map((c) => c.buffPercent)),
    spend, rerolls, blocked, chasedBest: Math.max(0, ...Object.values(chased)), chasedEquipped,
    freeBestParty: Math.max(0, ...freeParty), chaseBestParty: Math.max(0, ...chaseParty),
    satOffer, spendUntilSat, restIfRational: st.coins - spendUntilSat };
}

const q = (v: number[]) => { const s = [...v].sort((a, b) => a - b);
  return { p10: s[Math.floor((s.length - 1) * .1)]!, p50: s[Math.floor((s.length - 1) * .5)]!, p90: s[Math.floor((s.length - 1) * .9)]! }; };

describe('critic r3 scratch', () => {
  it('measures the value of a higher engraving and the offline economy', () => {
    const rows: Row[] = [];
    for (const policy of ['baseline', 'bestEquip'] as const)
      for (let seed = 1; seed <= 100; seed++) rows.push(run(seed, policy));
    const base = rows.filter((r) => r.policy === 'baseline');
    const best = rows.filter((r) => r.policy === 'bestEquip');
    const wins = base.filter((b, i) => best[i]!.kills > b.kills).length;
    const ties = base.filter((b, i) => best[i]!.kills === b.kills).length;
    const out = {
      baseline: { kills: q(base.map((r) => r.kills)), coins: q(base.map((r) => r.coins)),
        equippedBuff: q(base.map((r) => r.equippedBuff)), bestBuff: q(base.map((r) => r.bestBuff)),
        collected: q(base.map((r) => r.collected)) },
      bestEquip: { kills: q(best.map((r) => r.kills)), equippedBuff: q(best.map((r) => r.equippedBuff)),
        collected: q(best.map((r) => r.collected)) },
      pairedKills: { bestEquipWins: wins, ties, losses: 100 - wins - ties,
        medianDelta: q(base.map((b, i) => best[i]!.kills - b.kills)) },
      chase: { spend: q(base.map((r) => r.spend)), rerolls: q(base.map((r) => r.rerolls)),
        remaining: q(base.map((r) => r.coins - r.spend)), blockedSeeds: base.filter((r) => r.blocked > 0).length,
        chasedBest: q(base.map((r) => r.chasedBest)), chasedEquipped: q(base.map((r) => r.chasedEquipped)) },
      party: { freeBestParty: q(base.map((r) => r.freeBestParty)), chaseBestParty: q(base.map((r) => r.chaseBestParty)),
        freeReaches25: base.filter((r) => r.freeBestParty >= 25).length,
        chaseReaches25: base.filter((r) => r.chaseBestParty >= 25).length,
        chaseStrictlyBetter: base.filter((r) => r.chaseBestParty > r.freeBestParty).length,
        gain: q(base.map((r) => r.chaseBestParty - r.freeBestParty)),
        satOffer: q(base.filter((r) => r.satOffer > 0).map((r) => r.satOffer)),
        satSeeds: base.filter((r) => r.satOffer > 0).length,
        spendUntilSat: q(base.filter((r) => r.satOffer > 0).map((r) => r.spendUntilSat)),
        rationalRemaining: q(base.filter((r) => r.satOffer > 0).map((r) => r.restIfRational)) },
    };
    writeFileSync('/tmp/critic_r3.json', JSON.stringify(out, null, 2));
    process.stdout.write(JSON.stringify(out, null, 2) + '\n');
  }, 900000);
});

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/**
 * 3 different elements; unowned forms preferred. Slot 0 shows the top unlocked
 * rank while anything there is still unowned; once that rank is fully collected
 * it falls back to any unseen form, so the binder keeps growing past 14 instead
 * of re-offering the same top ten forever. The RNG draw count per slot is
 * unchanged, so the shared stream — and the pacing measured on it — is intact.
 */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const owned = (f: HeroForm): boolean => hero.collection.some((r) => r.formId === f.id);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    const eligible = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type));
    const top = eligible.filter((f) => f.rank === rank);
    const keepTop = top.some((f) => !owned(f)) || !eligible.some((f) => !owned(f));
    let pool = i === 0 && keepTop ? top : eligible;
    const unseen = pool.filter((f) => !owned(f));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;
/**
 * Releases needed for one soul. 2 keeps the 30 min payout at ~+11 souls, whose
 * measured upper bound on kills (+4.3%) stays inside the ±5% pacing budget.
 */
export const RELEASES_PER_SOUL = 2;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      releasedCount: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    releasedCount: save.releasedCount ?? 0,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    const drew = killed.boss && rng.next() < CAPTURE_CHANCE;
    if (drew && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    } else if (drew) {
      // A full roster used to void the draw in silence. Release it instead:
      // every second release pays one soul, and the event says whether the
      // roster's weakest keeper was worth less than what just walked away.
      state.releasedCount += 1;
      const souls = state.releasedCount % RELEASES_PER_SOUL === 0 ? 1 : 0;
      state.souls += souls;
      const released = companionPower({ id: '', speciesId: killed.speciesId, bossIndex: killed.index, level: 1, stars: 0 });
      const weakest = state.companions.reduce(
        (min, c) => (companionPower(c) < min ? companionPower(c) : min), released);
      events.push({ type: 'companionReleased', speciesId: killed.speciesId, bossIndex: killed.index,
        souls, strongerThanWeakest: weakest < released });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        releasedCount: state.releasedCount,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

// Save schema & tolerant parsing — SPEC F10/F29, Assumptions 7/21. Pure
// TypeScript, zero imports of electron/DOM/node. The app must never fail to
// boot because of a bad save: parseSave() NEVER throws — junk, missing and
// wrong-typed fields fall back per-field to DEFAULT_SAVE values. Disk always
// holds v3; older files are migrated on the way in (upgradeSave).

import { bigField } from './bignum.js';
import { monsterMaxHp } from './formulas.js';
import { isSpeciesId, SPECIES_IDS } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { parseHeroProgress } from './hero.js';
import type { HeroProgress } from './hero.js';

/** Roster cap (GAME_DESIGN_V2 §2/§3); collection.ts owns the gameplay copy. */
const ROSTER_CAP = 30;

/** PvP party cap (GAME_DESIGN_V3 §3/§4); collection.ts owns the gameplay copy. */
const PARTY_CAP = 5;

/** A captured boss (GAME_DESIGN_V2 §2). Ids are minted from nextCompanionId. */
export interface Companion {
  /** 'c1', 'c2' … — deterministic, never a uuid. */
  id: string;
  /** SpeciesId of the captured boss. */
  speciesId: string;
  /** Global monster index it was captured at → base power. */
  bossIndex: number;
  /** 1..COMPANION_MAX_LEVEL (10). */
  level: number;
  stars: number;
}

/** Legacy save shape (v1). Accepted as input, never written. */
export interface SaveFileV1 {
  version: 1;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  monsterHp: number;
}

/**
 * Persisted save-file schema, version 2. The engine's toSave() emits exactly
 * this shape; createEngine(save) resumes from it (SPEC F11/F29).
 */
export interface SaveFileV2 {
  version: 2;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  /** Decimal digits, ≥ '1' — HP is unbounded (SPEC F30). */
  monsterHp: string;
  /** Captured bosses, at most ROSTER_CAP entries. */
  companions: Companion[];
  nextCompanionId: number;
  souls: number;
  rebirths: number;
  /** Deepest monsterIndex ever reached. */
  bestIndex: number;
}

/**
 * Persisted save-file schema, version 3: v2 plus the manually picked PvP-only
 * party (GAME_DESIGN_V3 §3). Empty = the auto party is used.
 */
export interface SaveFileV3 extends Omit<SaveFileV2, 'version'> {
  version: 3;
  /** Randomly selected current species; absent in legacy saves. */
  monsterSpeciesId?: SpeciesId;
  /** Companion ids, at most PARTY_CAP, all present in `companions`. */
  pvpParty: string[];
  /** Additive v0.4 extension; v1–v3 saves retain their progress unchanged. */
  hero?: HeroProgress;
  /** Additive v0.4 extension; absent in older saves and read as 0. */
  releasedCount?: number;
}

/** The current schema. */
export type SaveFile = SaveFileV3;

/** Fresh-game values; also the per-field fallback for junk input. */
export const DEFAULT_SAVE: Readonly<SaveFileV3> = Object.freeze({
  version: 3 as const,
  level: 1,
  xp: 0,
  killCount: 0,
  coins: 0,
  items: Object.freeze({}) as Record<string, number>,
  monsterIndex: 0,
  monsterHp: String(monsterMaxHp(0)),
  companions: Object.freeze([] as Companion[]) as Companion[],
  nextCompanionId: 1,
  souls: 0,
  rebirths: 0,
  bestIndex: 0,
  pvpParty: Object.freeze([] as string[]) as string[],
  releasedCount: 0,
});

/**
 * Migrate a well-formed save to v3. v1 had no roster, souls or best depth;
 * v2 had no PvP party.
 */
export function upgradeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): SaveFileV3 {
  if (save.version === 3) return { ...save, releasedCount: save.releasedCount ?? 0 };
  if (save.version === 2) return { ...save, version: 3, pvpParty: [], releasedCount: 0 };
  return {
    version: 3,
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monsterIndex: save.monsterIndex,
    monsterHp: String(Math.max(1, Math.floor(save.monsterHp))),
    companions: [],
    nextCompanionId: 1,
    souls: 0,
    rebirths: 0,
    bestIndex: save.monsterIndex,
    pvpParty: [],
    releasedCount: 0,
  };
}

/**
 * Stable JSON: fixed top-level key order, items keys sorted, companions in
 * array order with fixed key order. Serializing the same logical save always
 * yields byte-identical text. Older input is upgraded first.
 */
export function serializeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): string {
  const v3 = upgradeSave(save);
  const items: Record<string, number> = {};
  for (const id of Object.keys(v3.items).sort()) {
    items[id] = v3.items[id] ?? 0;
  }
  return JSON.stringify({
    version: 3,
    level: v3.level,
    xp: v3.xp,
    killCount: v3.killCount,
    coins: v3.coins,
    items,
    monsterIndex: v3.monsterIndex,
    monsterSpeciesId: v3.monsterSpeciesId,
    monsterHp: v3.monsterHp,
    companions: v3.companions.map((c) => ({
      id: c.id,
      speciesId: c.speciesId,
      bossIndex: c.bossIndex,
      level: c.level,
      stars: c.stars,
    })),
    nextCompanionId: v3.nextCompanionId,
    souls: v3.souls,
    rebirths: v3.rebirths,
    bestIndex: v3.bestIndex,
    pvpParty: v3.pvpParty,
    releasedCount: v3.releasedCount ?? 0,
    hero: parseHeroProgress(v3.hero),
  });
}

/** Finite number → floored int clamped to `min`; anything else → fallback. */
function intField(value: unknown, fallback: number, min: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
  return Math.max(min, Math.floor(value));
}

/** Integer in [min, max] — the companion fields have no fallback, they drop. */
function isInt(value: unknown, min: number, max = Number.MAX_SAFE_INTEGER): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Keep only entries whose count is a finite number that floors to ≥ 1. */
function itemsField(value: unknown): Record<string, number> {
  const items: Record<string, number> = {};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return items;
  }
  for (const [id, count] of Object.entries(value)) {
    if (typeof count === 'number' && Number.isFinite(count) && Math.floor(count) >= 1) {
      items[id] = Math.floor(count);
    }
  }
  return items;
}

/**
 * Keep only fully valid companions (GAME_DESIGN_V2 §2): a bad entry is
 * dropped, it never defaults — a half-made companion would be worse than
 * none. Duplicate ids: first wins. At most ROSTER_CAP kept.
 */
function companionsField(value: unknown): Companion[] {
  const kept: Companion[] = [];
  if (!Array.isArray(value)) return kept;
  const seen = new Set<string>();
  for (const raw of value) {
    if (kept.length >= ROSTER_CAP) break;
    if (typeof raw !== 'object' || raw === null) continue;
    const c = raw as Record<string, unknown>;
    const id = c['id'];
    const speciesId = c['speciesId'];
    if (typeof id !== 'string' || id === '' || seen.has(id)) continue;
    if (typeof speciesId !== 'string' || !(SPECIES_IDS as readonly string[]).includes(speciesId)) {
      continue;
    }
    if (!isInt(c['bossIndex'], 0) || !isInt(c['level'], 1, 10) || !isInt(c['stars'], 0)) continue;
    seen.add(id);
    kept.push({ id, speciesId, bossIndex: c['bossIndex'], level: c['level'], stars: c['stars'] });
  }
  return kept;
}

/**
 * Keep only ids that are really on the parsed roster (a party pointing at a
 * consumed companion would resurrect it), deduped first-wins, PARTY_CAP kept.
 */
function pvpPartyField(value: unknown, companions: Companion[]): string[] {
  if (!Array.isArray(value)) return [];
  const ids = new Set(companions.map((c) => c.id));
  return [...new Set(value.filter((id): id is string => typeof id === 'string' && ids.has(id)))]
    .slice(0, PARTY_CAP);
}

/**
 * Tolerant parse of untrusted save data (SPEC F10/F29). Accepts anything —
 * pre-parsed JSON values (what main's load-state hands over) or raw JSON
 * text — and NEVER throws. Every invalid field independently falls back to
 * its DEFAULT_SAVE value; the input `version` is ignored (the shape decides)
 * and the output is always v3. Range clamping beyond that (e.g. monsterHp vs
 * the monster's maxHp) is the engine's job. Always returns fresh objects.
 */
export function parseSave(raw: unknown): SaveFileV3 {
  let value: unknown = raw;
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      value = null;
    }
  }
  const record: Record<string, unknown> =
    typeof value === 'object' && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};
  const companions = companionsField(record['companions']);
  const hero = parseHeroProgress(record['hero']);
  const species = record['monsterSpeciesId'];
  // Re-minting must never collide with an id already on the roster.
  let nextCompanionId = intField(record['nextCompanionId'], DEFAULT_SAVE.nextCompanionId, 1);
  for (const c of companions) {
    nextCompanionId = Math.max(nextCompanionId, Number(c.id.replace(/\D/g, '') || 0) + 1);
  }
  return {
    version: 3,
    level: intField(record['level'], DEFAULT_SAVE.level, 1),
    xp: intField(record['xp'], DEFAULT_SAVE.xp, 0),
    killCount: intField(record['killCount'], DEFAULT_SAVE.killCount, 0),
    coins: intField(record['coins'], DEFAULT_SAVE.coins, 0),
    items: itemsField(record['items']),
    monsterIndex: intField(record['monsterIndex'], DEFAULT_SAVE.monsterIndex, 0),
    ...(typeof species === 'string' && isSpeciesId(species) ? { monsterSpeciesId: species } : {}),
    monsterHp: (bigField(record['monsterHp']) ?? DEFAULT_SAVE.monsterHp).replace(/^0$/, '1'),
    companions,
    nextCompanionId,
    souls: intField(record['souls'], DEFAULT_SAVE.souls, 0),
    rebirths: intField(record['rebirths'], DEFAULT_SAVE.rebirths, 0),
    bestIndex: intField(record['bestIndex'], DEFAULT_SAVE.bestIndex, 0),
    pvpParty: pvpPartyField(record['pvpParty'], companions),
    releasedCount: intField(record['releasedCount'], 0, 0),
    ...(hero ? { hero } : {}),
  };
}

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/**
 * 3 different elements; unowned forms preferred. Slot 0 shows the top unlocked
 * rank while anything there is still unowned; once that rank is fully collected
 * it falls back to any unseen form, so the binder keeps growing past 14 instead
 * of re-offering the same top ten forever. The RNG draw count per slot is
 * unchanged, so the shared stream — and the pacing measured on it — is intact.
 */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const owned = (f: HeroForm): boolean => hero.collection.some((r) => r.formId === f.id);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    const eligible = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type));
    const top = eligible.filter((f) => f.rank === rank);
    const keepTop = top.some((f) => !owned(f)) || !eligible.some((f) => !owned(f));
    let pool = i === 0 && keepTop ? top : eligible;
    const unseen = pool.filter((f) => !owned(f));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;
/**
 * Releases needed for one soul. 2 keeps the 30 min payout at ~+11 souls, whose
 * measured upper bound on kills (+4.3%) stays inside the ±5% pacing budget.
 */
export const RELEASES_PER_SOUL = 2;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      releasedCount: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    releasedCount: save.releasedCount ?? 0,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    const drew = killed.boss && rng.next() < CAPTURE_CHANCE;
    if (drew && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    } else if (drew) {
      // A full roster used to void the draw in silence. Release it instead:
      // every second release pays one soul, and the event says whether the
      // roster's weakest keeper was worth less than what just walked away.
      state.releasedCount += 1;
      const souls = state.releasedCount % RELEASES_PER_SOUL === 0 ? 1 : 0;
      state.souls += souls;
      const released = companionPower({ id: '', speciesId: killed.speciesId, bossIndex: killed.index, level: 1, stars: 0 });
      const weakest = state.companions.reduce(
        (min, c) => (companionPower(c) < min ? companionPower(c) : min), released);
      events.push({ type: 'companionReleased', speciesId: killed.speciesId, bossIndex: killed.index,
        souls, strongerThanWeakest: weakest < released });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        releasedCount: state.releasedCount,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

// Progression formulas — FROZEN per SPEC Assumption 3 / GAME_ARCHITECTURE §2.
// Exact, integer, unit-tested. Do not tweak the curves.

/** +1 damage per hero level (visible stat). */
export const damageForLevel = (level: number): number => level;

/** Crit chance (rng-injected at the engine layer). */
export const CRIT_CHANCE = 0.1;

/** Crit damage multiplier. */
export const CRIT_MULT = 2;

// Party sorting asks for the same boss HP repeatedly on every volley/frame.
// ponytail: 512 indices bound the cache; the exact rational formula is unchanged.
const hpCache = new Map<number, bigint>();

/**
 * Monster max HP by 0-based global index: 10, 11, 13 … 40 @10 … 163 @20.
 * Exact rational 10*(115/100)^i in bigint (SPEC F30) — equal to the old
 * double for every i < 199, and unbounded beyond it.
 */
export const monsterMaxHp = (index: number): bigint => {
  const normalized = Math.max(0, Math.floor(index));
  const cached = hpCache.get(normalized);
  if (cached !== undefined) return cached;
  const i = BigInt(normalized);
  const hp = (10n * 115n ** i) / 100n ** i;
  if (hpCache.size >= 512) hpCache.clear();
  hpCache.set(normalized, hp);
  return hp;
};

/** XP granted for killing the monster at `index`. */
export const xpReward = (index: number): number => 5 + 3 * index;

/** XP needed to advance FROM `level` to the next: 20, 28, 39, 54 … */
export const xpToNext = (level: number): number =>
  Math.floor(20 * Math.pow(1.4, level - 1));

// Save schema & tolerant parsing — SPEC F10/F29, Assumptions 7/21. Pure
// TypeScript, zero imports of electron/DOM/node. The app must never fail to
// boot because of a bad save: parseSave() NEVER throws — junk, missing and
// wrong-typed fields fall back per-field to DEFAULT_SAVE values. Disk always
// holds v3; older files are migrated on the way in (upgradeSave).

import { bigField } from './bignum.js';
import { monsterMaxHp } from './formulas.js';
import { isSpeciesId, SPECIES_IDS } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { parseHeroProgress } from './hero.js';
import type { HeroProgress } from './hero.js';

/** Roster cap (GAME_DESIGN_V2 §2/§3); collection.ts owns the gameplay copy. */
const ROSTER_CAP = 30;

/** PvP party cap (GAME_DESIGN_V3 §3/§4); collection.ts owns the gameplay copy. */
const PARTY_CAP = 5;

/** A captured boss (GAME_DESIGN_V2 §2). Ids are minted from nextCompanionId. */
export interface Companion {
  /** 'c1', 'c2' … — deterministic, never a uuid. */
  id: string;
  /** SpeciesId of the captured boss. */
  speciesId: string;
  /** Global monster index it was captured at → base power. */
  bossIndex: number;
  /** 1..COMPANION_MAX_LEVEL (10). */
  level: number;
  stars: number;
}

/** Legacy save shape (v1). Accepted as input, never written. */
export interface SaveFileV1 {
  version: 1;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  monsterHp: number;
}

/**
 * Persisted save-file schema, version 2. The engine's toSave() emits exactly
 * this shape; createEngine(save) resumes from it (SPEC F11/F29).
 */
export interface SaveFileV2 {
  version: 2;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  /** Decimal digits, ≥ '1' — HP is unbounded (SPEC F30). */
  monsterHp: string;
  /** Captured bosses, at most ROSTER_CAP entries. */
  companions: Companion[];
  nextCompanionId: number;
  souls: number;
  rebirths: number;
  /** Deepest monsterIndex ever reached. */
  bestIndex: number;
}

/**
 * Persisted save-file schema, version 3: v2 plus the manually picked PvP-only
 * party (GAME_DESIGN_V3 §3). Empty = the auto party is used.
 */
export interface SaveFileV3 extends Omit<SaveFileV2, 'version'> {
  version: 3;
  /** Randomly selected current species; absent in legacy saves. */
  monsterSpeciesId?: SpeciesId;
  /** Companion ids, at most PARTY_CAP, all present in `companions`. */
  pvpParty: string[];
  /** Additive v0.4 extension; v1–v3 saves retain their progress unchanged. */
  hero?: HeroProgress;
  /** Additive v0.4 extension; absent in older saves and read as 0. */
  releasedCount?: number;
}

/** The current schema. */
export type SaveFile = SaveFileV3;

/** Fresh-game values; also the per-field fallback for junk input. */
export const DEFAULT_SAVE: Readonly<SaveFileV3> = Object.freeze({
  version: 3 as const,
  level: 1,
  xp: 0,
  killCount: 0,
  coins: 0,
  items: Object.freeze({}) as Record<string, number>,
  monsterIndex: 0,
  monsterHp: String(monsterMaxHp(0)),
  companions: Object.freeze([] as Companion[]) as Companion[],
  nextCompanionId: 1,
  souls: 0,
  rebirths: 0,
  bestIndex: 0,
  pvpParty: Object.freeze([] as string[]) as string[],
  releasedCount: 0,
});

/**
 * Migrate a well-formed save to v3. v1 had no roster, souls or best depth;
 * v2 had no PvP party.
 */
export function upgradeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): SaveFileV3 {
  if (save.version === 3) return { ...save, releasedCount: save.releasedCount ?? 0 };
  if (save.version === 2) return { ...save, version: 3, pvpParty: [], releasedCount: 0 };
  return {
    version: 3,
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monsterIndex: save.monsterIndex,
    monsterHp: String(Math.max(1, Math.floor(save.monsterHp))),
    companions: [],
    nextCompanionId: 1,
    souls: 0,
    rebirths: 0,
    bestIndex: save.monsterIndex,
    pvpParty: [],
    releasedCount: 0,
  };
}

/**
 * Stable JSON: fixed top-level key order, items keys sorted, companions in
 * array order with fixed key order. Serializing the same logical save always
 * yields byte-identical text. Older input is upgraded first.
 */
export function serializeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): string {
  const v3 = upgradeSave(save);
  const items: Record<string, number> = {};
  for (const id of Object.keys(v3.items).sort()) {
    items[id] = v3.items[id] ?? 0;
  }
  return JSON.stringify({
    version: 3,
    level: v3.level,
    xp: v3.xp,
    killCount: v3.killCount,
    coins: v3.coins,
    items,
    monsterIndex: v3.monsterIndex,
    monsterSpeciesId: v3.monsterSpeciesId,
    monsterHp: v3.monsterHp,
    companions: v3.companions.map((c) => ({
      id: c.id,
      speciesId: c.speciesId,
      bossIndex: c.bossIndex,
      level: c.level,
      stars: c.stars,
    })),
    nextCompanionId: v3.nextCompanionId,
    souls: v3.souls,
    rebirths: v3.rebirths,
    bestIndex: v3.bestIndex,
    pvpParty: v3.pvpParty,
    releasedCount: v3.releasedCount ?? 0,
    hero: parseHeroProgress(v3.hero),
  });
}

/** Finite number → floored int clamped to `min`; anything else → fallback. */
function intField(value: unknown, fallback: number, min: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
  return Math.max(min, Math.floor(value));
}

/** Integer in [min, max] — the companion fields have no fallback, they drop. */
function isInt(value: unknown, min: number, max = Number.MAX_SAFE_INTEGER): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Keep only entries whose count is a finite number that floors to ≥ 1. */
function itemsField(value: unknown): Record<string, number> {
  const items: Record<string, number> = {};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return items;
  }
  for (const [id, count] of Object.entries(value)) {
    if (typeof count === 'number' && Number.isFinite(count) && Math.floor(count) >= 1) {
      items[id] = Math.floor(count);
    }
  }
  return items;
}

/**
 * Keep only fully valid companions (GAME_DESIGN_V2 §2): a bad entry is
 * dropped, it never defaults — a half-made companion would be worse than
 * none. Duplicate ids: first wins. At most ROSTER_CAP kept.
 */
function companionsField(value: unknown): Companion[] {
  const kept: Companion[] = [];
  if (!Array.isArray(value)) return kept;
  const seen = new Set<string>();
  for (const raw of value) {
    if (kept.length >= ROSTER_CAP) break;
    if (typeof raw !== 'object' || raw === null) continue;
    const c = raw as Record<string, unknown>;
    const id = c['id'];
    const speciesId = c['speciesId'];
    if (typeof id !== 'string' || id === '' || seen.has(id)) continue;
    if (typeof speciesId !== 'string' || !(SPECIES_IDS as readonly string[]).includes(speciesId)) {
      continue;
    }
    if (!isInt(c['bossIndex'], 0) || !isInt(c['level'], 1, 10) || !isInt(c['stars'], 0)) continue;
    seen.add(id);
    kept.push({ id, speciesId, bossIndex: c['bossIndex'], level: c['level'], stars: c['stars'] });
  }
  return kept;
}

/**
 * Keep only ids that are really on the parsed roster (a party pointing at a
 * consumed companion would resurrect it), deduped first-wins, PARTY_CAP kept.
 */
function pvpPartyField(value: unknown, companions: Companion[]): string[] {
  if (!Array.isArray(value)) return [];
  const ids = new Set(companions.map((c) => c.id));
  return [...new Set(value.filter((id): id is string => typeof id === 'string' && ids.has(id)))]
    .slice(0, PARTY_CAP);
}

/**
 * Tolerant parse of untrusted save data (SPEC F10/F29). Accepts anything —
 * pre-parsed JSON values (what main's load-state hands over) or raw JSON
 * text — and NEVER throws. Every invalid field independently falls back to
 * its DEFAULT_SAVE value; the input `version` is ignored (the shape decides)
 * and the output is always v3. Range clamping beyond that (e.g. monsterHp vs
 * the monster's maxHp) is the engine's job. Always returns fresh objects.
 */
export function parseSave(raw: unknown): SaveFileV3 {
  let value: unknown = raw;
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      value = null;
    }
  }
  const record: Record<string, unknown> =
    typeof value === 'object' && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};
  const companions = companionsField(record['companions']);
  const hero = parseHeroProgress(record['hero']);
  const species = record['monsterSpeciesId'];
  // Re-minting must never collide with an id already on the roster.
  let nextCompanionId = intField(record['nextCompanionId'], DEFAULT_SAVE.nextCompanionId, 1);
  for (const c of companions) {
    nextCompanionId = Math.max(nextCompanionId, Number(c.id.replace(/\D/g, '') || 0) + 1);
  }
  return {
    version: 3,
    level: intField(record['level'], DEFAULT_SAVE.level, 1),
    xp: intField(record['xp'], DEFAULT_SAVE.xp, 0),
    killCount: intField(record['killCount'], DEFAULT_SAVE.killCount, 0),
    coins: intField(record['coins'], DEFAULT_SAVE.coins, 0),
    items: itemsField(record['items']),
    monsterIndex: intField(record['monsterIndex'], DEFAULT_SAVE.monsterIndex, 0),
    ...(typeof species === 'string' && isSpeciesId(species) ? { monsterSpeciesId: species } : {}),
    monsterHp: (bigField(record['monsterHp']) ?? DEFAULT_SAVE.monsterHp).replace(/^0$/, '1'),
    companions,
    nextCompanionId,
    souls: intField(record['souls'], DEFAULT_SAVE.souls, 0),
    rebirths: intField(record['rebirths'], DEFAULT_SAVE.rebirths, 0),
    bestIndex: intField(record['bestIndex'], DEFAULT_SAVE.bestIndex, 0),
    pvpParty: pvpPartyField(record['pvpParty'], companions),
    releasedCount: intField(record['releasedCount'], 0, 0),
    ...(hero ? { hero } : {}),
  };
}

// HUD painting (SPEC F21 + T14/T15 presentation): boxed monster HP bar,
// top-left `LV n` + XP bar, top-right kill/coin counters (with a collection
// pop flash), the pooled floating-damage-number system — numbers rise 8px
// and fade over 600ms; crits draw double-size and yellow (Manual M2) — and
// the flashing "LEVEL UP!" banner (Manual M3).
// DOM-free on purpose — everything draws through SpriteCanvas so the tests
// run under vitest's node environment (same pattern as sprites/sprite.ts).

import { ratio, xpToNext } from '../core/index.js';
import type { Effectiveness, GameState } from '../core/index.js';
import { heroReady, HERO_REST_MS } from '../core/hero.js';
import {
  COLORS,
  drawSprite,
  drawText,
  FONT_ADVANCE,
  FONT_H,
  FONT_W,
  fontSprite,
  glyphIndex,
  itemSprites,
  textWidth,
  TRANSPARENT,
} from './sprites/index.js';
import type { SpriteCanvas } from './sprites/index.js';

/** Gap between HUD chrome and the canvas edges, in game pixels. */
export const HUD_MARGIN = 2;
/** Keep counters below the drag strip, closer to the field. */
export const COUNTER_TOP = 16;
/** XP progress bar box size (top-left, under the LV text). */
export const XP_BAR_W = 40;
export const XP_BAR_H = 4;

/**
 * Boxed meter: 1px steel frame, void interior, proportional fill. A non-zero
 * ratio always shows at least 1px of fill; out-of-range/non-finite ratios
 * are clamped so a bad value can never paint outside the box.
 */
export function drawMeter(
  ctx: SpriteCanvas,
  x: number,
  y: number,
  w: number,
  h: number,
  ratio: number,
  fillColor: string,
): void {
  ctx.fillStyle = COLORS.steel;
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(x + 1, y + 1, w - 2, h - 2);
  const clamped = Number.isFinite(ratio) ? Math.min(1, Math.max(0, ratio)) : 0;
  const fill = clamped === 0 ? 0 : Math.max(1, Math.round((w - 2) * clamped));
  if (fill > 0) {
    ctx.fillStyle = fillColor;
    ctx.fillRect(x + 1, y + 1, fill, h - 2);
  }
}

/** Boxed red HP bar (drawn above the monster). */
export function drawHpBar(
  ctx: SpriteCanvas,
  x: number,
  y: number,
  w: number,
  h: number,
  hp: bigint,
  maxHp: bigint,
): void {
  drawMeter(ctx, x, y, w, h, ratio(hp, maxHp), COLORS.red);
}

/**
 * `LV n` text plus the XP progress bar, floating above the hero's head
 * (Assumption 17): `cx` is the hero's horizontal center, `bottom` sits just
 * above the hero's top row — the bar hugs the head, the label rides above it.
 */
export function drawLevelHud(
  ctx: SpriteCanvas,
  state: Readonly<GameState>,
  cx: number,
  bottom: number,
): void {
  const barX = Math.round(cx - XP_BAR_W / 2);
  const barY = bottom - XP_BAR_H;
  drawMeter(ctx, barX, barY, XP_BAR_W, XP_BAR_H, state.xp / xpToNext(state.level), COLORS.cyan);
  const label = `LV ${String(state.level)}`;
  drawText(ctx, label, Math.round(cx - textWidth(label) / 2), barY - FONT_H - 2);
  if (heroReady(state.level, state.hero)) {
    const ready = 'REBIRTH READY';
    drawText(ctx, ready, Math.round(cx - textWidth(ready) / 2), barY - 2 * (FONT_H + 2), { color: COLORS.yellow });
  }
}

/** Expedition gauge box: meter width, and where the soul count starts. */
export const EXPEDITION_W = 40;
export const EXPEDITION_H = 3;
export const EXPEDITION_SOULS_X = HUD_MARGIN + EXPEDITION_W + 2;

/**
 * Top-left expedition readout, drawn only while a reincarnation rest is
 * running: a draining meter for the wait plus the souls the current depth
 * already guarantees. Display only — it grants nothing and never moves, so
 * the whole thing stays inside x[2,60) y[16,21), clear of the hero, the
 * monster, the party, the counters and the banner.
 */
export function drawExpedition(ctx: SpriteCanvas, state: Readonly<GameState>): void {
  const remaining = state.hero?.restRemainingMs ?? 0;
  if (remaining <= 0) return;
  drawMeter(ctx, HUD_MARGIN, COUNTER_TOP, EXPEDITION_W, EXPEDITION_H,
    remaining / HERO_REST_MS, COLORS.blue);
  const souls = String(Math.max(1, Math.floor(state.monster.index / 8)));
  drawText(ctx, souls.length > 4 ? '9999' : souls, EXPEDITION_SOULS_X, COUNTER_TOP, { color: COLORS.orange });
}

/** 5×5 skull marker for the kill counter — HUD chrome, drawn directly. */
function drawSkullIcon(ctx: SpriteCanvas, x: number, y: number): void {
  ctx.fillStyle = COLORS.white;
  ctx.fillRect(x, y, 5, 3); // cranium
  ctx.fillRect(x + 1, y + 3, 3, 2); // jaw
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(x + 1, y + 1, 1, 1); // left eye socket
  ctx.fillRect(x + 3, y + 1, 1, 1); // right eye socket
  ctx.fillRect(x + 2, y + 4, 1, 1); // tooth gap
}

/** How long the coin counter stays "popped" after a drop arrives, ms. */
export const COUNTER_POP_MS = 150;

/**
 * Top-right HUD: skull × killCount row, coin × coins row (right-aligned).
 * While `coinPop` is set (a collected drop just arrived, T15) the coin row
 * pops: the count flashes white and the icon lifts one pixel.
 */
export function drawCounters(
  ctx: SpriteCanvas,
  state: Readonly<GameState>,
  viewW: number,
  coinPop = false,
): void {
  const kills = String(state.killCount);
  const killsX = viewW - HUD_MARGIN - textWidth(kills);
  drawText(ctx, kills, killsX, COUNTER_TOP);
  drawSkullIcon(ctx, killsX - 7, COUNTER_TOP);

  const coins = String(state.coins);
  const coinsX = viewW - HUD_MARGIN - textWidth(coins);
  drawText(ctx, coins, coinsX, COUNTER_TOP + FONT_H + 2, {
    color: coinPop ? COLORS.white : COLORS.yellow,
  });
  const iconY = COUNTER_TOP + FONT_H + (coinPop ? 0 : 1);
  drawSprite(ctx, itemSprites.coin, 0, coinsX - 8, iconY);
}

/** One pooled floating damage number. Slots are reused, never reallocated. */
export interface FloatingNumber {
  active: boolean;
  /** Horizontal center of the text, in game pixels. */
  x: number;
  /** Spawn baseline; the number rises FLOAT_RISE_PX over its lifetime. */
  y: number;
  text: string;
  crit: boolean;
  ageMs: number;
  /** Fresh-phase colour override (companion floats, F64); crit rules if unset. */
  color?: string;
}

/** Fixed pool size — key-mashing can never grow an unbounded array. */
export const FLOAT_POOL_SIZE = 16;
/** Lifetime of one floating number, ms. */
export const FLOAT_LIFE_MS = 600;
/** Total rise over the lifetime, game pixels. */
export const FLOAT_RISE_PX = 14;
/** Age fraction past which a float draws in its dim fade color. */
export const FLOAT_FADE_RATIO = 2 / 3;
/** Pixel scale of normal damage numbers (user change 2026-09-06: readable 2x glyphs with a 1-px outline). */
export const FLOAT_SCALE = 2;
/** Pixel scale of crit damage numbers (Manual M2: crits show larger — 3x, yellow, with a '!'). */
export const CRIT_FLOAT_SCALE = 3;
/** Crits rise this much further than normal floats (same lifetime, punchier). */
export const CRIT_RISE_MULT = 1.5;

export function floatColor(effectiveness: Effectiveness): string {
  return effectiveness === 'super'
    ? COLORS.yellow
    : effectiveness === 'weak'
      ? COLORS.steel
      : COLORS.white;
}

/** Pre-allocate a pool of inactive floating-number slots. */
export function createFloatPool(size: number = FLOAT_POOL_SIZE): FloatingNumber[] {
  return Array.from({ length: size }, () => ({
    active: false,
    x: 0,
    y: 0,
    text: '',
    crit: false,
    ageMs: 0,
  }));
}

/** Activate a slot: the first inactive one, else recycle the oldest active. */
export function spawnFloat(
  pool: FloatingNumber[],
  x: number,
  y: number,
  text: string,
  crit: boolean,
  color?: string,
): void {
  let slot = pool.find((f) => !f.active);
  if (slot === undefined) {
    for (const f of pool) {
      if (slot === undefined || f.ageMs > slot.ageMs) {
        slot = f;
      }
    }
  }
  if (slot === undefined) {
    return; // zero-size pool
  }
  slot.active = true;
  slot.x = x;
  slot.y = y;
  slot.text = text;
  slot.crit = crit;
  slot.color = color;
  slot.ageMs = 0;
}

/** Age every active slot; slots past FLOAT_LIFE_MS deactivate. */
export function tickFloats(pool: FloatingNumber[], dtMs: number): void {
  for (const f of pool) {
    if (!f.active) {
      continue;
    }
    f.ageMs += dtMs;
    if (f.ageMs >= FLOAT_LIFE_MS) {
      f.active = false;
    }
  }
}

/**
 * drawText at an integer pixel scale: every glyph pixel becomes a
 * scale×scale rect. Local to the HUD — the sprite/font modules stay
 * 1px-based (their data is covered by the T11 integrity sweep).
 */
function drawScaledText(
  ctx: SpriteCanvas,
  text: string,
  x: number,
  y: number,
  scale: number,
  color: string,
): void {
  if (scale === 1) {
    drawText(ctx, text, x, y, { color });
    return;
  }
  for (let i = 0; i < text.length; i++) {
    const rows = fontSprite.frames[glyphIndex(text.charAt(i))];
    if (rows === undefined) {
      continue; // unknown chars still advance a cell — stable layout
    }
    for (let ry = 0; ry < FONT_H; ry++) {
      const row = rows[ry];
      if (row === undefined) {
        continue;
      }
      for (let rx = 0; rx < FONT_W; rx++) {
        const ch = row.charAt(rx);
        if (ch === TRANSPARENT || ch === '') {
          continue;
        }
        ctx.fillStyle = color;
        ctx.fillRect(x + (i * FONT_ADVANCE + rx) * scale, y + ry * scale, scale, scale);
      }
    }
  }
}

/**
 * Draw active floating numbers, risen by age; the last third of the
 * lifetime fades to a dim color. Crits draw double-size and yellow
 * (bottom-anchored so the bigger glyphs grow upward, not into the monster).
 */
export function drawFloats(ctx: SpriteCanvas, pool: FloatingNumber[]): void {
  for (const f of pool) {
    if (!f.active) continue;
    const scale = f.crit ? CRIT_FLOAT_SCALE : FLOAT_SCALE;
    const text = f.crit ? `${f.text}!` : f.text;
    const faded = f.ageMs >= FLOAT_LIFE_MS * FLOAT_FADE_RATIO;
    const color = faded
      ? f.crit
        ? COLORS.orange
        : COLORS.steel
      : (f.color ?? (f.crit ? COLORS.yellow : COLORS.white));
    const rise = Math.round(FLOAT_RISE_PX * (f.crit ? CRIT_RISE_MULT : 1) * (f.ageMs / FLOAT_LIFE_MS));
    const x = Math.round(f.x - (textWidth(text) * scale) / 2);
    const y = f.y - rise - (scale - 1) * FONT_H;
    // 1-px void outline (4 offsets) under the glyphs: numbers stay readable over any art.
    for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
      drawScaledText(ctx, text, x + ox, y + oy, scale, COLORS.void);
    }
    drawScaledText(ctx, text, x, y, scale, color);
  }
}

/** Draw the active fever state directly above the hero, with a dark outline. */
export function drawFeverLabel(ctx: SpriteCanvas, cx: number, heroTop: number): void {
  const scale = 2;
  const x = Math.round(cx - (textWidth(FEVER_TEXT) * scale) / 2);
  const y = heroTop - 26;
  for (const [ox, oy] of [[-1, 0], [1, 0], [0, -1], [0, 1]] as const) {
    drawScaledText(ctx, FEVER_TEXT, x + ox, y + oy, scale, COLORS.void);
  }
  drawScaledText(ctx, FEVER_TEXT, x, y, scale, COLORS.yellow);
}

// ---------------------------------------------------------------------------
// "LEVEL UP!" banner (Manual M3): a centered double-size flash triggered by
// the engine's levelUp event. Single timer slot — a second level-up simply
// restarts it (no unbounded state).
// ---------------------------------------------------------------------------

/** Banner text — every glyph exists in font.ts's GLYPH_CHARS. */
export const LEVEL_UP_TEXT = 'LEVEL UP!';
export const FEVER_TEXT = 'FEVER!';
export const VICTORY_TEXT = 'VICTORY!';
export const DEFEAT_TEXT = 'DEFEAT';
/** Banner lifetime, ms. */
export const BANNER_MS = 1200;
/** Banner pixel scale. */
export const BANNER_SCALE = 2;
/** Flash cadence: the banner alternates yellow/white every interval. */
export const BANNER_FLASH_MS = 100;
/** Banner top edge, game pixels (clear of the HUD rows and the monster). */
export const BANNER_Y = 20;

/** The banner's single timer slot. */
export interface Banner {
  active: boolean;
  ageMs: number;
  text: string;
}

/** Fresh, inactive banner state. */
export function createBanner(): Banner {
  return { active: false, ageMs: 0, text: LEVEL_UP_TEXT };
}

/** (Re)start the banner — called on every levelUp event. */
export function showBanner(banner: Banner, text = LEVEL_UP_TEXT): void {
  banner.active = true;
  banner.ageMs = 0;
  banner.text = text;
}

/** Age the banner; it deactivates after BANNER_MS. */
export function tickBanner(banner: Banner, dtMs: number): void {
  if (!banner.active) {
    return;
  }
  banner.ageMs += dtMs;
  if (banner.ageMs >= BANNER_MS) {
    banner.active = false;
  }
}

/** Draw the flashing centered banner while it is active. */
export function drawBanner(ctx: SpriteCanvas, banner: Banner, viewW: number): void {
  if (!banner.active) {
    return;
  }
  const flashPhase = Math.floor(banner.ageMs / BANNER_FLASH_MS) % 2;
  const color = flashPhase === 0 ? COLORS.yellow : COLORS.white;
  const x = Math.round((viewW - textWidth(banner.text) * BANNER_SCALE) / 2);
  drawScaledText(ctx, banner.text, x, BANNER_Y, BANNER_SCALE, color);
}

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/**
 * 3 different elements; unowned forms preferred. Slot 0 shows the top unlocked
 * rank while anything there is still unowned; once that rank is fully collected
 * it falls back to any unseen form, so the binder keeps growing past 14 instead
 * of re-offering the same top ten forever. The RNG draw count per slot is
 * unchanged, so the shared stream — and the pacing measured on it — is intact.
 */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const owned = (f: HeroForm): boolean => hero.collection.some((r) => r.formId === f.id);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    const eligible = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type));
    const top = eligible.filter((f) => f.rank === rank);
    const keepTop = top.some((f) => !owned(f)) || !eligible.some((f) => !owned(f));
    let pool = i === 0 && keepTop ? top : eligible;
    const unseen = pool.filter((f) => !owned(f));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;
/**
 * Releases needed for one soul. 2 keeps the 30 min payout at ~+11 souls, whose
 * measured upper bound on kills (+4.3%) stays inside the ±5% pacing budget.
 */
export const RELEASES_PER_SOUL = 2;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      releasedCount: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    releasedCount: save.releasedCount ?? 0,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    const drew = killed.boss && rng.next() < CAPTURE_CHANCE;
    if (drew && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    } else if (drew) {
      // A full roster used to void the draw in silence. Release it instead:
      // every second release pays one soul, and the event says whether the
      // roster's weakest keeper was worth less than what just walked away.
      state.releasedCount += 1;
      const souls = state.releasedCount % RELEASES_PER_SOUL === 0 ? 1 : 0;
      state.souls += souls;
      const released = companionPower({ id: '', speciesId: killed.speciesId, bossIndex: killed.index, level: 1, stars: 0 });
      const weakest = state.companions.reduce(
        (min, c) => (companionPower(c) < min ? companionPower(c) : min), released);
      events.push({ type: 'companionReleased', speciesId: killed.speciesId, bossIndex: killed.index,
        souls, strongerThanWeakest: weakest < released });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        releasedCount: state.releasedCount,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

