// Real engine, injected RNG/clock, no wall time or input hooks. A simulation
// measures pacing; it cannot certify that a human finds the game enjoyable.
import { writeFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { createEngine, heroReady, mulberry32 } from '../src/core/index.js';

type Profile = 'active' | 'idle' | 'intermittent';
interface Sample { minutes: number; profile: Profile; seed: number; kills: number; firstOfferSec: number | null;
  reincarnations: number; collected: number; coins: number; companions: number; longestKillGapSec: number;
  /** v0.4 expedition payoff: full-roster releases, and how many were the first card unseen. */
  released: number; souls: number; unseenFirstCards: number; offers: number }

function simulate(profile: Profile, seed: number): Sample[] {
  const engine = createEngine(null, mulberry32(seed));
  const result: Sample[] = [];
  let firstOfferSec: number | null = null;
  let lastKill = 0;
  let longestKillGapSec = 0;
  let released = 0;
  let unseenFirstCards = 0;
  let offers = 0;
  for (let sec = 1; sec <= 1800; sec++) {
    // All profiles get a two-minute onboarding. Idle then stops input;
    // intermittent works 15 seconds per minute; active inputs twice a second.
    const inputs = sec <= 120 || profile === 'active' || (profile === 'intermittent' && sec % 60 < 15) ? 2 : 0;
    let killed = false;
    for (let i = 0; i < inputs; i++) {
      const hit = engine.attack('keyboard');
      killed = hit.some((e) => e.type === 'monsterKilled') || killed;
      released += hit.filter((e) => e.type === 'companionReleased').length;
    }
    // Do not short-circuit engine steps when an earlier input killed.
    const events = engine.tick(1000);
    killed = events.some((e) => e.type === 'monsterKilled') || killed;
    released += events.filter((e) => e.type === 'companionReleased').length;
    if (killed) {
      longestKillGapSec = Math.max(longestKillGapSec, sec - lastKill);
      lastKill = sec;
    }
    const state = engine.getState();
    if (heroReady(state.level, state.hero)) {
      firstOfferSec ??= sec;
      engine.apply({ type: 'heroOffer' });
      const hero = engine.getState().hero!;
      // Choose the first card, without any gold rerolls — the same policy the
      // v0.4 baseline used, so before/after numbers stay comparable.
      offers++;
      if (!hero.collection.some((r) => r.formId === hero.choices[0]!.formId)) unseenFirstCards++;
      engine.apply({ type: 'heroChoose', formId: hero.choices[0]!.formId, offerSerial: hero.offerSerial });
    }
    if ([300, 900, 1800].includes(sec)) {
      const current = engine.getState();
      result.push({ minutes: sec / 60, profile, seed, kills: current.killCount,
        firstOfferSec, reincarnations: current.hero?.reincarnations ?? 0,
        collected: current.hero?.collection.length ?? 0, coins: current.coins,
        companions: current.companions.length,
        longestKillGapSec: Math.max(longestKillGapSec, sec - lastKill),
        released, souls: current.souls, unseenFirstCards, offers });
    }
  }
  return result;
}

describe('v0.4 deterministic pacing playtest', () => {
  it('checks 100 seeds across active, warm-idle and intermittent play at 5/15/30 minutes', () => {
    const samples = (['active', 'idle', 'intermittent'] as const).flatMap((profile) =>
      Array.from({ length: 100 }, (_, i) => {
        const sample = simulate(profile, i + 1);
        if (process.env.DESMON_BALANCE_REPORT && (i + 1) % 25 === 0) process.stdout.write(`${profile}: ${i + 1}/100 seeds\n`);
        return sample;
      }).flat());
    const quantiles = (values: number[]) => {
      const sorted = [...values].sort((a, b) => a - b);
      return { p10: sorted[Math.floor((sorted.length - 1) * .1)]!, p50: sorted[Math.floor((sorted.length - 1) * .5)]!, p90: sorted[Math.floor((sorted.length - 1) * .9)]! };
    };
    const scenarios = (['active', 'idle', 'intermittent'] as const).flatMap((profile) => [5, 15, 30].map((minutes) => {
      const rows = samples.filter((s) => s.profile === profile && s.minutes === minutes);
      return { profile, minutes, samples: rows.length,
        firstOfferReached: rows.filter((r) => r.firstOfferSec !== null).length,
        firstOfferSec: quantiles(rows.flatMap((r) => r.firstOfferSec === null ? [] : [r.firstOfferSec])),
        kills: quantiles(rows.map((r) => r.kills)), reincarnations: quantiles(rows.map((r) => r.reincarnations)),
        collected: quantiles(rows.map((r) => r.collected)), coins: quantiles(rows.map((r) => r.coins)),
        longestKillGapSec: quantiles(rows.map((r) => r.longestKillGapSec)),
        released: quantiles(rows.map((r) => r.released)), souls: quantiles(rows.map((r) => r.souls)),
        unseenFirstCardRatio: rows.reduce((sum, r) => sum + (r.offers === 0 ? 1 : r.unseenFirstCards / r.offers), 0) / rows.length,
        fullRosters: rows.filter((r) => r.companions === 30).length };
    }));
    const report = { version: '0.4.0', kind: 'simulated-not-human', seeds: '1..100',
      inputModel: '2 inputs/s; 120s onboarding, then idle=0/s; intermittent=15s/min; choose first offer, no rerolls, no companion management',
      scenarios, rawSamples: samples };
    if (process.env.DESMON_BALANCE_REPORT) writeFileSync(process.env.DESMON_BALANCE_REPORT, JSON.stringify(report, null, 2) + '\n');
    expect(samples).toHaveLength(900);
    expect(samples.every((s) => s.coins >= 0 && s.collected <= 50 && s.companions <= 30)).toBe(true);
    const active = scenarios.find((s) => s.profile === 'active' && s.minutes === 5)!;
    expect(active.firstOfferReached).toBe(100);
    expect(active.firstOfferSec.p90).toBeLessThanOrEqual(300);
    for (const profile of ['active', 'idle', 'intermittent']) {
      const early = scenarios.find((s) => s.profile === profile && s.minutes === 5)!;
      const late = scenarios.find((s) => s.profile === profile && s.minutes === 30)!;
      expect(late.kills.p50).toBeGreaterThan(early.kills.p50);
      expect(late.reincarnations.p50).toBeGreaterThan(early.reincarnations.p50);
    }
    // H4 — the v0.4 expedition payoff may not move the measured pacing more
    // than the ±5% budget the design was approved under (baseline: first offer
    // 79s, active 30 min 1,238 kills / 15 reincarnations).
    const active30 = scenarios.find((s) => s.profile === 'active' && s.minutes === 30)!;
    expect(active.firstOfferSec.p50).toBeGreaterThanOrEqual(74);
    expect(active.firstOfferSec.p50).toBeLessThanOrEqual(84);
    expect(active30.kills.p50).toBeGreaterThanOrEqual(1176);
    expect(active30.kills.p50).toBeLessThanOrEqual(1300);
    expect(active30.reincarnations.p50).toBe(15);
    // H1/H2 — a full roster no longer eats captures in silence, and H3 — the
    // first card is always an unseen form while the binder is incomplete.
    expect(active30.fullRosters).toBe(100);
    expect(active30.released.p10).toBeGreaterThanOrEqual(8);
    expect(active30.released.p50).toBeGreaterThanOrEqual(18);
    expect(active30.unseenFirstCardRatio).toBe(1);
    // The binder used to stall at 14 forms. It now tracks the reincarnation
    // count exactly, which is the ceiling the 120s rest imposes.
    expect(samples.every((s) => s.collected === Math.min(50, s.reincarnations))).toBe(true);
    expect(active30.collected.p10).toBe(active30.reincarnations.p10);
    expect(active30.collected.p50).toBe(15);
  }, 30_000);
});

// v0.4 "expedition payoff" — the three changes the v4 fun review approved:
// A3' a full roster releases a boss instead of voiding the draw in silence,
// A5' the hero offer's first slot opens up once the top rank is fully owned,
// A1' a display-only rest gauge that must never overlap the existing HUD.
// Pure core + the DOM-free HUD, so everything runs under vitest's node env.

import { describe, expect, it } from 'vitest';
import {
  createEngine,
  DEFAULT_SAVE,
  HERO_FORMS,
  HERO_REST_MS,
  monsterForIndex,
  mulberry32,
  RELEASES_PER_SOUL,
  rollHeroChoices,
  ROSTER_CAP,
} from '../src/core/index.js';
import type { Companion, GameEvent, GameState, HeroProgress, SaveFile } from '../src/core/index.js';
import { newHeroProgress } from '../src/core/hero.js';
import {
  COUNTER_TOP,
  drawExpedition,
  EXPEDITION_H,
  EXPEDITION_SOULS_X,
  EXPEDITION_W,
  HUD_MARGIN,
} from '../src/renderer/hud.js';
import type { SpriteCanvas } from '../src/renderer/sprites/index.js';

/** A save whose roster is already at the cap, so every capture is a release. */
function fullRosterSave(): SaveFile {
  const companions: Companion[] = Array.from({ length: ROSTER_CAP }, (_, i) => ({
    id: `c${i + 1}`,
    speciesId: 'slime',
    // Ascending power, so the weakest keeper is always c1.
    bossIndex: i,
    level: 1,
    stars: 0,
  }));
  return { ...DEFAULT_SAVE, companions, nextCompanionId: ROSTER_CAP + 1, items: {}, pvpParty: [] };
}

/** Drive one engine for `attacks` inputs and return every event it emitted. */
function play(save: SaveFile | null, seed: number, attacks: number): { state: GameState; events: GameEvent[] } {
  const engine = createEngine(save, mulberry32(seed));
  const events: GameEvent[] = [];
  for (let i = 0; i < attacks; i++) events.push(...engine.attack('keyboard'));
  return { state: engine.getState(), events };
}

describe('A3 — a full roster releases the boss instead of voiding it (H1/H2)', () => {
  it('never swallows a capture draw: every full-roster boss draw emits an event', () => {
    // Invariant, not a distribution: over 100 seeds the count of releases must
    // equal the count of successful draws that the cap turned away, and the
    // engine must never capture past the cap.
    for (let seed = 1; seed <= 100; seed++) {
      const { state, events } = play(fullRosterSave(), seed, 4000);
      const released = events.filter((e) => e.type === 'companionReleased');
      const captured = events.filter((e) => e.type === 'bossCaptured');
      expect(captured).toHaveLength(0);
      expect(state.companions).toHaveLength(ROSTER_CAP);
      expect(state.releasedCount).toBe(released.length);
      // Souls follow the fixed conversion, with no partial credit lost.
      const paid = released.reduce((sum, e) => sum + (e.type === 'companionReleased' ? e.souls : 0), 0);
      expect(paid).toBe(Math.floor(released.length / RELEASES_PER_SOUL));
      expect(state.souls).toBe(paid);
    }
  });

  it('pays exactly one soul on every RELEASES_PER_SOUL-th release and persists the tally', () => {
    const { state, events } = play(fullRosterSave(), 7, 4000);
    const released = events.filter((e) => e.type === 'companionReleased');
    expect(released.length).toBeGreaterThan(0);
    let seen = 0;
    for (const e of released) {
      if (e.type !== 'companionReleased') continue;
      seen++;
      expect(e.souls).toBe(seen % RELEASES_PER_SOUL === 0 ? 1 : 0);
      expect(e.bossIndex).toBeGreaterThanOrEqual(0);
    }
    // The tally survives a save/resume so the conversion keeps its parity.
    const resumed = createEngine({ ...fullRosterSave(), releasedCount: state.releasedCount }, mulberry32(1));
    expect(resumed.getState().releasedCount).toBe(state.releasedCount);
    expect(resumed.toSave().releasedCount).toBe(state.releasedCount);
  });

  it('flags whether the released boss beat the roster\'s weakest keeper', () => {
    // A roster of deep bosses is worth more than any early release …
    const strong: SaveFile = {
      ...fullRosterSave(),
      companions: Array.from({ length: ROSTER_CAP }, (_, i) => ({
        id: `c${i + 1}`, speciesId: 'dragon', bossIndex: 400, level: 1, stars: 0,
      })),
    };
    const strongRuns = play(strong, 3, 2000).events
      .filter((e): e is Extract<GameEvent, { type: 'companionReleased' }> => e.type === 'companionReleased');
    expect(strongRuns.length).toBeGreaterThan(0);
    expect(strongRuns.every((e) => !e.strongerThanWeakest)).toBe(true);

    // … while a roster of index-0 slimes is beaten by anything deeper.
    const weak: SaveFile = {
      ...fullRosterSave(),
      companions: Array.from({ length: ROSTER_CAP }, (_, i) => ({
        id: `c${i + 1}`, speciesId: 'slime', bossIndex: 0, level: 1, stars: 0,
      })),
    };
    const weakRuns = play(weak, 3, 2000).events
      .filter((e): e is Extract<GameEvent, { type: 'companionReleased' }> => e.type === 'companionReleased');
    expect(weakRuns.length).toBeGreaterThan(0);
    expect(weakRuns.some((e) => e.strongerThanWeakest)).toBe(true);
  });

  it('leaves the RNG stream untouched: an open roster plays exactly as before', () => {
    // The capture draw is still consumed once per boss kill, so a run that
    // never fills its roster must be bit-identical to the pre-change pacing.
    for (const seed of [1, 17, 55, 90]) {
      const open = play(null, seed, 3000);
      expect(open.events.filter((e) => e.type === 'companionReleased')).toHaveLength(0);
      expect(open.state.releasedCount).toBe(0);
      expect(open.state.companions.length).toBeLessThanOrEqual(ROSTER_CAP);
    }
  });
});

describe('A5 — the offer keeps finding unseen forms past the top rank (H3)', () => {
  const heroAt = (reincarnations: number, collection: HeroProgress['collection']): HeroProgress =>
    ({ ...newHeroProgress(), reincarnations, collection });

  it('offers an unseen form in slot 0 once the top rank is fully collected', () => {
    // Everything at rank 5 owned, nothing below it — the old rule was stuck
    // re-offering the same ten forms forever.
    const topRank = HERO_FORMS.filter((f) => f.rank === 5);
    const hero = heroAt(20, topRank.map((f) => ({ formId: f.id, buffPercent: 20 })));
    let unseenFirst = 0;
    for (let seed = 1; seed <= 100; seed++) {
      const choices = rollHeroChoices(hero, mulberry32(seed));
      expect(choices).toHaveLength(3);
      if (!hero.collection.some((r) => r.formId === choices[0]!.formId)) unseenFirst++;
    }
    expect(unseenFirst).toBe(100);
  });

  it('still guarantees the newest rank while that rank has anything unseen', () => {
    for (let reincarnations = 0; reincarnations < 5; reincarnations++) {
      const rank = Math.min(5, reincarnations + 1);
      for (let seed = 1; seed <= 20; seed++) {
        const first = rollHeroChoices(heroAt(reincarnations, []), mulberry32(seed))[0]!;
        expect(HERO_FORMS.find((f) => f.id === first.formId)?.rank).toBe(rank);
      }
    }
  });

  it('always offers three distinct elements and keeps the roll range', () => {
    const owned = HERO_FORMS.slice(0, 40).map((f) => ({ formId: f.id, buffPercent: 25 }));
    for (const collection of [[], owned, HERO_FORMS.map((f) => ({ formId: f.id, buffPercent: 25 }))]) {
      for (let seed = 1; seed <= 50; seed++) {
        const choices = rollHeroChoices(heroAt(20, collection), mulberry32(seed));
        const types = choices.map((r) => HERO_FORMS.find((f) => f.id === r.formId)!.type);
        expect(new Set(types).size).toBe(3);
        for (const roll of choices) {
          expect(roll.buffPercent).toBeGreaterThanOrEqual(10);
          expect(roll.buffPercent).toBeLessThanOrEqual(25);
        }
      }
    }
  });

  it('consumes the same number of RNG draws as the previous rule', () => {
    // Two draws per slot, six per offer — the shared stream is what the
    // pacing baseline was measured on, so its length may not move.
    for (const collection of [[], HERO_FORMS.map((f) => ({ formId: f.id, buffPercent: 25 }))]) {
      let draws = 0;
      const base = mulberry32(42);
      const counting = { next: (): number => { draws++; return base.next(); } };
      rollHeroChoices(heroAt(20, collection), counting);
      expect(draws).toBe(6);
    }
  });

  it('drives the binder past the old 14-form ceiling under an always-accept policy', () => {
    // Simulated policy, not a human: accept the first card every time.
    const collected = new Set<string>();
    let hero = newHeroProgress();
    const rng = mulberry32(9);
    for (let i = 0; i < 50; i++) {
      const choices = rollHeroChoices(hero, rng);
      const pick = choices[0]!;
      collected.add(pick.formId);
      hero = {
        ...hero,
        reincarnations: hero.reincarnations + 1,
        collection: hero.collection.some((r) => r.formId === pick.formId)
          ? hero.collection
          : [...hero.collection, pick],
      };
    }
    // The old slot-0 rule capped this at 14 (4 low ranks + 10 at rank 5).
    expect(collected.size).toBe(50);
  });
});

describe('A1 — the expedition gauge is display-only and stays out of the way (H2b/H7)', () => {
  interface Rect { x: number; y: number; w: number; h: number }

  const paint = (hero?: HeroProgress, monsterIndex = 40): Rect[] => {
    const rects: Rect[] = [];
    const ctx: SpriteCanvas = {
      fillStyle: '',
      fillRect(x: number, y: number, w: number, h: number): void { rects.push({ x, y, w, h }); },
    };
    const monster = monsterForIndex(monsterIndex);
    const state = {
      ...createEngine(null, mulberry32(1)).getState(),
      monster, monsterHp: monster.maxHp,
      ...(hero ? { hero } : {}),
    } as GameState;
    drawExpedition(ctx, state);
    return rects;
  };

  const resting = (restRemainingMs: number): HeroProgress => ({ ...newHeroProgress(), restRemainingMs });

  it('paints nothing at all when no rest is running', () => {
    expect(paint(undefined)).toEqual([]);
    expect(paint(resting(0))).toEqual([]);
    expect(paint(newHeroProgress())).toEqual([]);
  });

  it('drains monotonically over the rest and disappears at zero (H2b)', () => {
    const fillWidth = (ms: number): number => {
      const rects = paint(resting(ms));
      // drawMeter paints frame, interior, then the fill — the fill is last.
      return rects.length >= 3 ? rects[rects.length - 1]!.w : 0;
    };
    let prev = Number.POSITIVE_INFINITY;
    for (let ms = HERO_REST_MS; ms > 0; ms -= HERO_REST_MS / 20) {
      const w = fillWidth(ms);
      expect(w).toBeLessThanOrEqual(prev);
      prev = w;
    }
    expect(paint(resting(0))).toEqual([]);
  });

  it('never leaves its declared pixel budget, whatever the depth (H7)', () => {
    // The whole readout lives in x[2,60) y[16,21) — clear of the hero
    // (x[66,94)), the monster and counters (x>=150) and the banner (y=20 is
    // only reached by text baselines at x>=64).
    const boxRight = EXPEDITION_SOULS_X + 4 * 4; // <=4 glyphs at FONT_ADVANCE 4
    expect(HUD_MARGIN).toBe(2);
    expect(COUNTER_TOP).toBe(16);
    expect(boxRight).toBeLessThanOrEqual(60);
    for (const index of [0, 8, 100, 5000, 10_000_000]) {
      for (const rect of paint(resting(HERO_REST_MS / 2), index)) {
        expect(rect.x).toBeGreaterThanOrEqual(HUD_MARGIN);
        expect(rect.x + rect.w).toBeLessThanOrEqual(60);
        expect(rect.y).toBeGreaterThanOrEqual(COUNTER_TOP);
        expect(rect.y + rect.h).toBeLessThanOrEqual(COUNTER_TOP + 5);
      }
    }
    expect(EXPEDITION_W).toBe(40);
    expect(EXPEDITION_H).toBe(3);
  });

  it('changes no game state — it only reads (H2b: display is not a reward)', () => {
    const engine = createEngine(null, mulberry32(5));
    const before = engine.toSave();
    paint(resting(HERO_REST_MS));
    expect(engine.toSave()).toEqual(before);
  });
});

// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/**
 * 3 different elements; unowned forms preferred. Slot 0 shows the top unlocked
 * rank while anything there is still unowned; once that rank is fully collected
 * it falls back to any unseen form, so the binder keeps growing past 14 instead
 * of re-offering the same top ten forever. The RNG draw count per slot is
 * unchanged, so the shared stream — and the pacing measured on it — is intact.
 */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const owned = (f: HeroForm): boolean => hero.collection.some((r) => r.formId === f.id);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    const eligible = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type));
    const top = eligible.filter((f) => f.rank === rank);
    const keepTop = top.some((f) => !owned(f)) || !eligible.some((f) => !owned(f));
    let pool = i === 0 && keepTop ? top : eligible;
    const unseen = pool.filter((f) => !owned(f));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

// Attack engine — SPEC F06/F07/F08, Assumption 8 (damage applies at input
// time; animation/timing state lives elsewhere). Pure TypeScript, zero
// imports of electron/DOM/node. All randomness comes from the injected Rng.

import { activeCompanions, applyCollection, companionPower, ROSTER_CAP } from './collection.js';
import type { CollectionAction } from './collection.js';
import {
  createFever,
  feverActive,
  feverInput,
  feverTick,
  FEVER_MULT,
} from './fever.js';
import {
  CRIT_CHANCE,
  CRIT_MULT,
  xpReward,
  xpToNext,
} from './formulas.js';
import { rollLoot } from './loot.js';
import { attackDelayOf, BOSS_COIN_MULT, BOSS_XP_MULT, monsterForIndex, SPECIES_IDS, typeOf } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { mulberry32 } from './rng.js';
import { effectiveness, effectivePower } from './types-chart.js';
import type { Rng } from './rng.js';
import { upgradeSave } from './save.js';
import { applyHeroAction, copyHeroProgress, heroAttackPower, heroBuffedPower, parseHeroProgress } from './hero.js';
import type { Companion, SaveFile, SaveFileV1, SaveFileV2, SaveFileV3 } from './save.js';
import type { GameEvent, GameState, InputSource } from './types.js';

/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = 0.35;
/**
 * Releases needed for one soul. 2 keeps the 30 min payout near +11 souls. The
 * measured effect on pacing is +0.16% kills over 100 seeds (an all-at-once
 * +10 souls control bounds it at +4.3%), well inside the ±5% budget.
 */
export const RELEASES_PER_SOUL = 2;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      releasedCount: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    releasedCount: save.releasedCount ?? 0,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, SPECIES_IDS[Math.floor(rng.next() * SPECIES_IDS.length)] ?? SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One extra draw per boss kill, ALWAYS consumed; a full roster voids
    // the capture. The next species is drawn after rewards and capture.
    const drew = killed.boss && rng.next() < CAPTURE_CHANCE;
    if (drew && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    } else if (drew) {
      // A full roster used to void the draw in silence. Release it instead:
      // every second release pays one soul, and the event says whether the
      // roster's weakest keeper was worth less than what just walked away.
      state.releasedCount += 1;
      const souls = state.releasedCount % RELEASES_PER_SOUL === 0 ? 1 : 0;
      state.souls += souls;
      const released = companionPower({ id: '', speciesId: killed.speciesId, bossIndex: killed.index, level: 1, stars: 0 });
      const weakest = state.companions.reduce(
        (min, c) => (companionPower(c) < min ? companionPower(c) : min), released);
      events.push({ type: 'companionReleased', speciesId: killed.speciesId, bossIndex: killed.index,
        souls, strongerThanWeakest: weakest < released });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    state.monster = randomMonster(killed.index + 1, rng);
    state.monsterHp = state.monster.maxHp;
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        heroAttackPower(state.level, state.souls, state.hero?.reincarnations) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        state.monster = randomMonster(0, rng);
        state.monsterHp = state.monster.maxHp;
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        releasedCount: state.releasedCount,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
      };
    },
  };
}

